async function uploadPhoto(draftId,role,file,replacement){
 const raw=await file.arrayBuffer();
 const digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',raw))].map(n=>n.toString(16).padStart(2,'0')).join('');
 const key=[draftId,role,digest,replacement??''].join(':'),op=pending.get(key)??crypto.randomUUID();pending.set(key,op);let accepted=false;
 try{
  const result=await api(`/drafts/${draftId}/photos?role=${role}&filename=${encodeURIComponent(file.name)}${replacement?'&replace='+encodeURIComponent(replacement):''}`,{method:'POST',raw,headers:{'Content-Type':'application/octet-stream','X-Workspace-Revision':String(workspace.revision),'Idempotency-Key':op}});
  accepted=true;await load();pending.delete(key);return result;
 }catch(e){if(!accepted&&e.status&&e.status<500)pending.delete(key);throw e;}
}
function batchView(){return `<button class="back" data-nav="intake">${icon('back')}Back to intake</button>${heading('A WHOLE STACK, ONE SAVED QUEUE','Batch photo intake','Upload one front per card, or add optional front/back pairs. Review each piece after saving.')}<section class="panel"><div class="panel-body"><div class="form-error" role="alert"></div><div class="form-grid"><label class="field">Type<select id="batch-kind">${options([['comic','Comics'],['card','Trading cards'],['other','Other collectibles']],batch.details?.kind??'comic')}</select></label>${field('Storage location for this batch','batchLocation',batch.details?.location??'',{placeholder:'You can edit each piece later'})}</div><div class="note"><strong>Selection order matters:</strong> front, back, front, back. Check every pair below and use Swap if needed. Up to 500 photos per queue, within your remaining storage allowance. Titles, prices, condition, and final review come next.</div><div class="note">Photo space remaining: ${storageSize(photoStorage.limitBytes-photoStorage.usedBytes)}. Single-photo cards still need identity, value, and condition review. Back photos are optional for every card, regardless of price or type.</div><input type="hidden" name="batchCutoff" value="5.00"><label class="field batch-picker">Add card fronts only<input id="batch-single-files" type="file" multiple accept="image/jpeg,image/png,image/webp,image/heic" aria-label="Add card fronts only"></label><label class="field batch-picker">Choose paired photos<input id="batch-files" type="file" multiple accept="image/jpeg,image/png,image/webp,image/heic" aria-label="Choose paired photos"></label><div id="batch-progress"></div></div></section>`;}
function renderBatchProgress(){
 const root=$('#batch-progress');if(!root)return;
 const location=$('[name="batchLocation"]');if(location){location.id='batch-location';location.disabled=batch.started||batch.running;}
 $('#batch-single-files').disabled=batch.started||batch.running||$('#batch-kind').value!=='card';$('[name="batchCutoff"]').disabled=batch.started||batch.running;$('#batch-kind').disabled=batch.started||batch.running;$('#batch-files').disabled=batch.started||batch.running;
 const saved=batch.items.filter(item=>item.status==='saved').length;
 const connection=$('.connection');if(connection)connection.textContent=batch.running?'Saving photos':batch.unfinished?(batch.started?'Batch paused':'Photos queued'):'Saved';
 root.innerHTML=`<div class="batch-toolbar"><div role="status" aria-live="polite"><strong>${saved} / ${batch.items.length} pieces saved</strong><p>${batch.running?(batch.pauseRequested?'Pausing after this piece…':'Saving originals…'):batch.unfinished?(batch.started?'Paused. Saved work is safe. Retry the unfinished pieces.':'Check the photo groups, then start saving.'):'Saved pieces are waiting in Intake for your review.'}</p></div><div class="actions">${batch.items.length?`<button class="btn" data-action="batch-clear" ${batch.running?'disabled':''}>Clear queue</button>`:''}${batch.running?`<button class="btn" data-action="batch-pause" ${batch.pauseRequested?'disabled':''}>Pause after this piece</button>`:batch.unfinished?`<button class="btn primary" data-action="batch-start">${batch.started?(batch.items.some(item=>item.status==='error')?'Retry unfinished':'Resume batch'):'Save batch'}</button>`:batch.items.length?'<button class="btn primary" data-nav="intake">Review saved intake</button>':''}</div></div><div class="batch-grid">${batch.items.map((item,index)=>`<article class="batch-card"><div class="batch-card-head"><strong>Piece ${index+1}</strong><span class="pill ${item.status==='error'?'error':item.status==='saved'?'received':'draft'}">${{waiting:'Waiting',saving:'Saving',saved:'Saved for review',error:'Needs attention'}[item.status]}</span></div><div class="batch-photos">${item.files.map((entry,i)=>`<figure><img loading="lazy" src="${esc(entry.url)}" alt="Piece ${index+1} ${i===0?'front':'back'} preview"><figcaption><strong>${i===0?'Front':'Back'}</strong><span>${esc(entry.file.name)}</span></figcaption></figure>`).join('')}</div>${item.error?`<p class="batch-error" role="alert">${esc(item.error)}</p>`:''}<div class="batch-card-foot"><small>${item.uploaded.length}/${item.files.length} originals saved</small>${!batch.started&&!batch.running?`<button class="btn small" data-batch-remove="${item.id}">Remove</button>${item.files.length===2?`<button class="btn small" data-batch-swap="${item.id}" aria-label="Swap photos for piece ${index+1}">Swap</button>`:''}`:''}${item.status==='saved'?`<button class="text-btn" data-draft="${item.draftId}" ${batch.running?'disabled':''}>Review piece →</button>`:''}</div></article>`).join('')}</div><div class="note">Keep this tab open until saving finishes. You can pause between pieces. A failed upload keeps the saved draft and photos so a retry continues from there. Nothing in this queue counts as inventory until you review and confirm it.</div>`;
}
