async function api(path,{method='GET',data,headers={},raw}={}){
 let r;try{r=await fetch('/api'+path,{method,credentials:'same-origin',cache:'no-store',headers:{...(data!==undefined?{'Content-Type':'application/json'}:{}),...(method!=='GET'&&session?.csrf?{'X-CSRF-Token':session.csrf}:{}),...headers},body:raw??(data!==undefined?JSON.stringify(data):undefined)});}catch{throw Error('BTCore could not be reached. Check your connection and retry; saved work stays in Intake.');}
 let result;try{result=await r.json();}catch{throw Error('BTCore could not be reached. Check your connection and try again.');}
 if(!r.ok){const e=Error(result.error??'The request failed.');e.status=r.status;throw e;}return result;
}
async function load(){let result=await api('/workspace');const defaults=(result.listingDefaults??[]).filter(e=>!quickEdits.has(e.id));if(defaults.length){const applied=await api('/listing-defaults',{method:'POST',data:{expectedRevision:result.state.revision,operationId:crypto.randomUUID(),data:{entries:defaults}}});for(const [oldId,newId] of Object.entries(applied.batchReplacements??{})){if(deskBatchId===oldId)deskBatchId=newId;if(sessionStorage.getItem(pendingListingKey)===oldId)sessionStorage.setItem(pendingListingKey,newId);}result=await api('/workspace');}workspace=result.state;collx=result.collx??{rows:[]};publication=result.publication??{batches:[]};stats=result.summary;photoStorage=result.photoStorage;ai=result.ai;preparationNeeded=result.preparationNeeded??[];approvedListings=new Set(result.approvedListings??[]);for(const [id,content] of selectedListings)if(!workspace.drafts.some(d=>d.id===id&&listingContent(d)===content&&!listingProblems(d).length&&!approvedListings.has(id)))selectedListings.delete(id);}
async function save(path,data){
 const key=path+JSON.stringify(data),op=pending.get(key)??crypto.randomUUID();pending.set(key,op);let accepted=false;
 try{const result=await api(path,{method:'POST',data:{expectedRevision:workspace.revision,operationId:op,data}});accepted=true;await load();pending.delete(key);return result;}catch(e){if(!accepted&&e.status&&e.status<500)pending.delete(key);throw e;}
}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function error(e){const target=$('#desk-bulk:not([hidden]) .form-error')??$('#modal[open] .form-error')??$('#main .form-error')??$('.login-box .form-error');if(target){target.textContent=e.message;target.scrollIntoView({block:'nearest'});}else toast(e.message);}
async function run(fn){if(busy)return;busy=true;const buttons=[...document.querySelectorAll('button[type="submit"]:not(:disabled),button[data-write]:not(:disabled)')],surfaces=view==='batch'?[]:[...document.querySelectorAll('#main,#modal[open]')];buttons.forEach(b=>b.disabled=true);surfaces.forEach(s=>{s.inert=true;s.setAttribute('aria-busy','true');});try{await fn();}catch(e){error(e);}finally{busy=false;buttons.forEach(b=>b.disabled=false);[...new Set([...surfaces,...document.querySelectorAll('#main,#modal[open]')])].forEach(s=>{s.inert=false;s.removeAttribute('aria-busy');});}}
