function home(){const queue=workspace.drafts.filter(d=>d.status==='draft').slice(-4).reverse(),items=workspace.inventory.items.slice(-4).reverse();return `${heading('YOUR COLLECTING BUSINESS, ORGANIZED','Make room for what’s next.','Every card. Every comic. A place and a plan.','<button class="btn" data-nav="mirror">Side-by-side trial</button>'+bulkIntakeButton()+newIntakeButton())}<section class="welcome"><div><div class="eyebrow">FROM THE RECEIVING TRAY TO THE VAULT</div><h2>Photograph. Review. Put it away.</h2><p>Keep the original photos, record the details, and give every piece a home. Your progress stays here when you step away.</p></div><div class="orbit">${icon('box')}</div></section>${metrics()}<div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Keep things moving <span class="count">${queue.length}</span></h2><button class="text-btn" data-nav="intake">View intake →</button></div>${queue.length?queue.map(d=>`<div class="queue-item">${artwork(d)}<div class="queue-info"><button class="list-link" data-draft="${esc(d.id)}">${esc(d.title||'Untitled intake')}</button><small>${esc(d.sku)} · ${d.photos.length} photos · ${esc(d.location||'Location needed')}</small></div>${pill(d.status)}<button class="text-btn row-arrow" data-draft="${esc(d.id)}" aria-label="Open ${esc(d.title||'intake')}">→</button></div>`).join(''):empty('Your intake queue is clear.','Start with the next card or comic on your desk.',newIntakeButton())}</section><section class="panel"><div class="panel-head"><h2>Around the Vault</h2>${icon('vault').replace('<svg','<svg width="17" height="17"')}</div><div class="panel-body"><div class="mini-row"><span>Collection holds</span><strong>${workspace.inventory.items.filter(i=>i.status==='hold'&&remaining(i)>0).length}</strong></div><div class="mini-row"><span>Recorded sales</span><strong>${stats.sales}</strong></div><div class="mini-row"><span>Known net profit</span><strong class="money-positive">${money(stats.net)}</strong></div><div class="note"><strong>A good habit:</strong> record the storage location before a piece goes into the Vault. Future you will thank you.</div></div></section><section class="panel"><div class="panel-head"><h2>Recently added</h2><button class="text-btn" data-nav="inventory">Open the Vault →</button></div>${items.length?items.map(i=>`<div class="queue-item">${artwork(i)}<div class="queue-info"><button class="list-link" data-item="${esc(i.id)}">${esc(i.title)}</button><small>${esc(i.location||'No location')} · ${esc(i.sku)}</small></div><strong class="amount">${askingMoney(i.askCents)}</strong></div>`).join(''):empty('A clean start.','Add inventory directly, or use intake to attach front and back photos.',`<button class="btn" data-action="new-item">Add inventory</button>`)}</section><section class="panel"><div class="panel-head"><h2>Your next step</h2></div><div class="panel-body"><h3>${queue.length?'Finish a saved intake.':'Start with one piece.'}</h3><p>${queue.length?'The photos and details you saved are ready when you are. Review the identity and condition before confirming it.':'Pick a card or comic, upload both sides, and record the title, price, and location.'}</p><button class="btn secondary" data-nav="intake">Open intake ${icon('arrow')}</button></div></section></div>`;}
function inventory(){return `${heading('A PLACE FOR EVERY PIECE','The Vault','Physical inventory, recorded costs, and where to find it.',`<a class="btn secondary" href="/api/export/inventory.csv">${icon('download')}Export CSV</a><label class="btn">Import CDP inventory<input id="inventory-cdp-csv" type="file" accept=".csv,text/csv" hidden></label><button class="btn" data-action="location-audit">Location issues</button><button class="btn primary" data-action="new-item">${icon('plus')}Add item</button>`)}${metrics()}<section class="panel"><div class="panel-head"><h2>Inventory <span class="count">${workspace.inventory.items.length}</span></h2><span class="muted">USD</span></div><div class="filters"><div class="search-wrap">${icon('search')}<input type="search" id="search" aria-label="Search inventory" placeholder="Search title, player, SKU, location…" value="${esc(query)}"></div><select id="kind-filter" aria-label="Filter by type">${options([['all','All types'],['card','Cards'],['comic','Comics'],['bulk','Bulk lots'],['other','Other']],kind)}</select><select id="status-filter" aria-label="Filter by status">${options([['all','All statuses'],['intake','In intake'],['ready','Ready to list'],['hold','Holds'],['listed','Listed'],['sold','Sold']],statusFilter)}</select></div><div id="inventory-table"></div></section>`;}
function renderTable(){const q=query.toLowerCase().trim(),items=workspace.inventory.items.filter(i=>(kind==='all'||i.kind===kind)&&(statusFilter==='all'||itemStatus(i)===statusFilter)&&(!q||inventorySearchText(i).includes(q.normalize('NFD').replace(/[\u0300-\u036f]/g,'')))),rows=items.slice((page-1)*15,page*15);$('#inventory-table').innerHTML=rows.length?`<div class="table-scroll"><table><thead><tr><th>Item / identification</th><th>Location</th><th>Asking / unit</th><th>Quantity</th><th>Status</th></tr></thead><tbody>${rows.map(i=>`<tr><td><div class="item-cell">${artwork(i)}<div><button class="list-link" data-item="${esc(i.id)}">${esc(i.title)}</button><small>${esc(i.sku)}${i.gradeCompany?' · '+esc(i.gradeCompany+' '+i.grade):''}${i.serial?' · '+esc(i.serial):''}</small></div></div></td><td>${esc(i.location||'LOCATION MISSING')}${i.locationConflicts?.length?'<strong class="batch-error">Location conflict — review before picking</strong>':locationStatus(i.physicalLocation,i.location)!=='recorded'?'<small>'+esc(locationStatus(i.physicalLocation,i.location))+'</small>':''}</td><td class="amount">${askingMoney(i.askCents)}</td><td>${remaining(i)} / ${i.quantity}</td><td>${pill(itemStatus(i))}</td></tr>${i.source?.draftId?'<tr><td colspan="5">'+quickControls(workspace.drafts.find(d=>d.id===i.source.draftId))+'</td></tr>':''}`).join('')}</tbody></table></div><div class="table-footer"><span>${(page-1)*15+1}–${Math.min(page*15,items.length)} of ${items.length} records</span><div class="actions">${page>1?'<button class="btn small" data-action="previous">Previous</button>':''}${page*15<items.length?'<button class="btn small" data-action="next">Next</button>':''}</div></div>`:empty(workspace.inventory.items.length?'No matching items.':'Your inventory starts here.',workspace.inventory.items.length?'Try another title, SKU, or filter.':'Give your first piece a location and record what you paid.',`<button class="btn primary" data-action="new-item">Add item</button>`);updateQuickBar();}
function intake(){return `${heading('FROM CAMERA TO COLLECTION','The intake desk','Original photos and saved details. Pick up where you left off.',`<button class="btn" data-action="batch-intake">${icon('camera')}Batch photos</button>${newIntakeButton()}`)}${preparationBanner()}<div class="tabs" aria-label="Intake status">${[['draft','Needs review'],['received','In the Vault'],['archived','Archived']].map(([value,label])=>`<button class="tab ${draftFilter===value?'active':''}" data-intake-filter="${value}" aria-pressed="${draftFilter===value}">${label} <span class="count">${workspace.drafts.filter(d=>d.status===value).length}</span></button>`).join('')}</div><div class="intake-search"><input id="intake-search" type="search" aria-label="Search intake" placeholder="Search title, SKU, or location…" value="${esc(draftQuery)}"></div>${deskSurface()}<div id="intake-list">${intakeList()}</div>`;}
function conditionSelect(label,name,d){const c=conditionChoices(d);return '<label class="field">'+esc(label)+'<select name="'+esc(name)+'" aria-label="'+esc(label)+'">'+options([['','Choose condition…'],...c.values.map(v=>[v,v])],c.value)+'</select>'+(d.conditionChoice?.source==='default'&&d.conditionChoice.value===d.condition?'<small>Default: '+esc(d.conditionChoice.rule)+'. Change if needed.</small>':'')+(c.legacy?'<small class="legacy-condition">Previous assessment: '+esc(c.legacy)+'. Choose an eBay condition.</small>':'')+'</label>';}
function quickControls(original){
 if(!original||original.status==='archived')return '';
 const b=publication.batches.find(b=>b.status!=='cancelled'&&b.entries.some(e=>e.draftId===original.id)),item=workspace.inventory.items.find(i=>i.id===original.itemId);
 if(b&&(b.publicationApproved||!['staged','preparing','ready'].includes(b.status))||item&&(['listed','hold'].includes(item.status)||remaining(item)<1))return '<p class="muted">Listing edits are locked until its marketplace/stock status is reviewed.</p>';
 if(['queued','running'].includes(original.preparation?.status))return '<p class="muted">Quick edits available when preparation finishes.</p>';
 const d={...original,...quickEdits.get(original.id)?.fields};
 return '<form class="quick-edit" data-quick-edit="'+esc(d.id)+'"><label class="checkbox bulk-row-selector"><input type="checkbox" data-edit-select="'+esc(d.id)+'" aria-label="Select '+esc(d.title||d.sku)+' for bulk edit" '+(bulkSelection.has(d.id)?'checked':'')+'>Select for bulk edit</label><div class="quick-fields">'+field('Price ($)','askCents',d.askCents==null||priceNeedsReview(original)&&!Object.hasOwn(quickEdits.get(d.id)?.fields??{},'askCents')?'':roundAskingCents(d.askCents)/100,{type:'number',min:1,step:1})+conditionSelect('Condition','condition',d)+'<label class="field">Shipping<select name="shippingMode" aria-label="Shipping">'+options([['auto',d.kind==='card'?'Auto · PWE / parcel':'Review packaging & shipping cost'],['parcel','Protective parcel'],['lot','Card lot · review shipping'],['review','Review shipping cost']],d.shippingMode??'auto')+'</select></label></div><p class="quick-route" role="status">'+esc(routeLabels[shippingRoute(d)])+(d.kind==='comic'?' · comics never inherit card postage':'')+'</p><div class="actions"><button class="btn small" type="submit" data-write>Save row</button><button class="text-btn" type="button" data-action="quick-discard" data-row-id="'+esc(d.id)+'">Discard row changes</button><span class="quick-status">'+(quickEdits.has(d.id)?'Unsaved changes':'Saved')+'</span></div></form>';
}
function trackQuickEdit(target){
 const form=target.closest('[data-quick-edit]');if(!form||!target.name)return;
 const id=form.dataset.quickEdit,d=workspace.drafts.find(d=>d.id===id),edit=quickEdits.get(id)??{content:listingContent(d),fields:{}};
 edit.fields[target.name]=target.name==='askCents'?(target.value===''?null:Math.round(Number(target.value)*100)):target.value;
 quickEdits.set(id,edit);form.querySelector('.quick-status').textContent='Unsaved changes';
 form.querySelector('.quick-route').textContent=routeLabels[shippingRoute({...d,...edit.fields,askCents:roundAskingCents(edit.fields.askCents??d.askCents)})];
 updateQuickBar();
}
function shownEditIds(){return [...new Set([...document.querySelectorAll('[data-edit-select]')].map(el=>el.dataset.editSelect))];}
function updateQuickBar(){
 if(deskVisible()){updateDeskToolbar();return;}
 let bar=$('#quick-save-bar');if(!bar){bar=document.createElement('section');bar.id='quick-save-bar';bar.className='quick-save-bar';bar.setAttribute('aria-label','Bulk listing edits');$('#main')?.prepend(bar);}
 const shown=shownEditIds();
 if(bar){bar.hidden=!shown.length&&!quickEdits.size&&!bulkSelection.size;bar.innerHTML='<div class="bulk-edit-summary"><strong>'+bulkSelection.size+' selected</strong><span>'+(quickEdits.size?quickEdits.size+' unsaved row'+(quickEdits.size===1?'':'s'):'Select cards to change them together')+'</span></div><div class="bulk-edit-actions">'+(shown.length?'<button class="btn small" data-action="quick-select-all">Select all shown ('+Math.min(shown.length,500)+')</button>':'')+'<button class="text-btn" data-action="quick-clear-selection" '+(bulkSelection.size?'':'disabled')+'>Clear</button><button class="btn primary" data-action="quick-bulk-edit" '+(bulkSelection.size?'':'disabled')+'>Edit selected ('+bulkSelection.size+')</button>'+(quickEdits.size?'<button class="btn" data-action="quick-save-all">Save changes</button>':'')+'</div>';}
 if(bulkSelection.size)bar.insertAdjacentHTML('beforeend','<div class="bulk-selection-dock"><strong>'+bulkSelection.size+' selected</strong><button class="btn primary" data-action="quick-bulk-edit">Edit '+bulkSelection.size+' selected</button></div>');
 for(const el of document.querySelectorAll('[data-edit-select]'))el.checked=bulkSelection.has(el.dataset.editSelect);
}
function showBulkEditor(){
 const cards=workspace.drafts.filter(d=>bulkSelection.has(d.id));if(!cards.length)throw Error('Select cards to update first.');
 if(cards.length>500)throw Error('Select no more than 500 cards.');
 bulkRowSnapshots=cards.map(d=>({id:d.id,content:quickEdits.get(d.id)?.content??listingContent(d),fields:{...quickEdits.get(d.id)?.fields}}));
 const values=sharedConditionChoices(cards);
 const body='<form id="bulk-row-form"><p>Only these '+cards.length+' selected cards will change. Blank fields stay unchanged. Your unsaved row edits are included.</p><div class="form-grid">'+field('Price for selected cards ($)','bulkPrice','',{type:'number',min:1,step:'0.01'})+'<label class="field">eBay condition<select name="bulkCondition" aria-label="eBay condition" '+(values.length?'':'disabled')+'>'+options([['','Keep each condition'],...values.map(v=>[v,v])],'')+'</select>'+(!values.length?'<small>Select the same item type to change condition together. Graded and raw cards use different conditions.</small>':'')+'</label><label class="field full">Shipping for selected cards<select name="bulkShipping" aria-label="Shipping for selected cards">'+options([['','Keep each shipping method'],['auto','Auto · PWE / parcel'],['parcel','Protective parcel'],['lot','Card lot · review shipping'],['review','Review shipping cost']],'')+'</select></label></div><details class="compact-card-list"><summary>Review '+cards.length+' selected cards</summary><ul>'+cards.map(d=>'<li>'+esc(d.title||d.sku)+' · '+askingMoney(d.askCents)+' · '+esc(d.condition||'Condition needed')+'</li>').join('')+'</ul></details><div class="actions flow-actions"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary" data-write>Save '+cards.length+' selected</button></div></form>';
 if(deskVisible()){const panel=$('#desk-bulk');panel.innerHTML='<h2>Bulk edit '+cards.length+' cards</h2><div class="form-error" role="alert"></div>'+body.replace('data-action="close"','data-action="desk-close-bulk"');panel.hidden=false;panel.scrollIntoView({block:'start'});}else modal('Bulk edit '+cards.length+' cards',body);
}
async function saveBulkEditor(form){
 const f=new FormData(form),fields={};if(f.get('bulkPrice')!=='')fields.askCents=roundAskingCents(cents(f.get('bulkPrice')));if(f.get('bulkCondition'))fields.condition=String(f.get('bulkCondition'));if(f.get('bulkShipping'))fields.shippingMode=String(f.get('bulkShipping'));
 const entries=await Promise.all(bulkRowSnapshots.map(async e=>({id:e.id,fingerprint:await contentFingerprint(e.content),fields:{...e.fields,...fields}})));
 if(entries.some(e=>!Object.keys(e.fields).length))throw Error('Choose a price, condition or shipping method to update.');
 const result=await save('/listing-rows',{entries});for(const e of entries){quickEdits.delete(e.id);if(!deskVisible())bulkSelection.delete(e.id);}
 for(const [oldId,newId] of Object.entries(result.batchReplacements??{})){if(sessionStorage.getItem(pendingListingKey)===oldId)sessionStorage.setItem(pendingListingKey,newId);if(deskBatchId===oldId)deskBatchId=newId;}
 finishDirty=false;close();render();toast(entries.length+' selected '+(entries.length===1?'card':'cards')+' updated. Unselected cards unchanged.');
}
async function saveQuickRows(ids=[...quickEdits.keys()]){
 const entries=await Promise.all(ids.filter(id=>quickEdits.has(id)).map(async id=>({id,fingerprint:await contentFingerprint(quickEdits.get(id).content),fields:quickEdits.get(id).fields})));
 if(!entries.length)return;
 const result=await save('/listing-rows',{entries});
 for(const e of entries)quickEdits.delete(e.id);
 for(const [oldId,newId] of Object.entries(result.batchReplacements??{})){if(sessionStorage.getItem(pendingListingKey)===oldId)sessionStorage.setItem(pendingListingKey,newId);if(deskBatchId===oldId)deskBatchId=newId;}
 toast(Object.keys(result.batchReplacements??{}).length?'Saved. eBay preview will refresh before your final approval.':'Listing details saved.');
 return result;
}
function intakeList(all=false){const q=draftQuery.trim().toLowerCase(),drafts=workspace.drafts.filter(d=>(all?d.status!=='archived':d.status===draftFilter)&&(!deskVisible()||!deskAttentionRows().some(x=>x.id===d.id))&&(!q||[d.title,d.sku,d.location].join(' ').toLowerCase().includes(q))).reverse();return drafts.length?`${deskVisible()?'<details id="desk-other-cards" '+(deskFocused?'':'open')+'><summary>All other cards ('+drafts.length+')</summary>':''}<div class="draft-grid">${drafts.map(d=>`<article class="draft-card"><button class="draft-open" data-draft="${esc(d.id)}"><div class="draft-cover">${d.photos.length?d.photos.map(p=>`<img src="/api/photos/${esc(p.id)}/preview" alt="${esc(p.role)} photo" loading="lazy">`).join(''):icon('camera')}${pill(d.status)}</div><div class="draft-copy"><h3>${esc(d.title||'Untitled intake')}</h3>${d.preparation?`<small>${esc(d.preparation.status==='complete'?'Details saved':d.preparation.status==='error'?'Preparation needs attention':d.preparation.status==='running'?'Preparing…':'Queued for preparation')}</small>`:''}<p>${esc(d.sku)} · ${esc(d.location||'Location needed')}</p><div class="draft-bottom"><span>${d.photos.length} photos${missingPhotos(d).length?' · incomplete':''}</span><span>${askingMoney(d.askCents)}</span></div></div></button>${quickControls(d)}${deskVisible()?deskCardStatus(d):''}</article>`).join('')}</div>${deskVisible()?'</details>':''}`:`<section class="panel">${empty(q?'No matching intake.':draftFilter==='archived'?'No archived intake.':draftFilter==='received'?'No confirmed intake yet.':'Your intake queue is clear.',draftFilter==='archived'?'Archived drafts keep their photos and can be restored.':'Start an intake or choose a batch of front and back photos.',draftFilter==='draft'?newIntakeButton():'')}</section>`;}
function renderIntakeList(){if($('#intake-list'))$('#intake-list').innerHTML=intakeList(view==='publication');updateQuickBar();}

function options(values,value){return values.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('');}
function field(label,name,value='',{type='text',required=false,full=false,placeholder='',help='',min,step}={}){return `<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${min!==undefined?`min="${min}"`:''} ${step?`step="${step}"`:''} placeholder="${esc(placeholder)}">${help?`<small>${help}</small>`:''}</label>`;}
function itemFields(d={},isDraft=false){return `<div class="form-grid">${field('Title','title',d.title,{full:true,required:!isDraft,placeholder:'Series, issue, year, variant — or player and card'})}<label class="field">Type<select name="kind">${options([['comic','Comic'],['card','Trading card'],['bulk','Bulk lot'],['other','Other collectible']],d.kind??'comic')}</select></label>${field('Storage location','location',d.location,{placeholder:'COMIC-AUC-01'})}${field('Player / character','subject',d.subject)}${field('Year','year',d.year)}${field('Set / series','setName',d.setName)}${field('Card / issue number','number',d.number)}${field('Parallel / variant','parallel',d.parallel)}${field('Serial number','serial',d.serial,{placeholder:'e.g. 001/199'})}${field('Grading company','gradeCompany',d.gradeCompany)}${field('Grade','grade',d.grade)}${field('Certificate number','cert',d.cert)}<label class="checkbox"><input name="autograph" type="checkbox" ${d.autograph?'checked':''}>Autograph physically verified</label></div>`;}
function photoPolicyFields(d){if(d.kind==='card')return `<input type="hidden" name="photoPolicy" value="${esc(d.photoPolicy??'value-based')}"><input type="hidden" name="cardClass" value="${esc(d.cardClass??'unknown')}"><input type="hidden" name="singlePhotoMax" value="${esc(dollars(d.singlePhotoMaxCents??500))}"><label class="checkbox"><input name="memorabilia" type="checkbox" ${d.memorabilia?'checked':''}>Memorabilia / relic card</label><div class="note">One front photo is enough for any card. Back photos are optional, regardless of price, autograph, numbering or grade. An unpictured reverse remains unassessed.</div>`;return `<div class="form-grid"><label class="field">Photo rule<select name="photoPolicy" aria-label="Photo rule">${options([['two-sided','Always front and back'],['value-based','One photo for cards within the cutoff']],d.photoPolicy??'two-sided')}</select></label><label class="field">Card classification<select name="cardClass" aria-label="Card classification">${options([['unknown','Needs identification'],['standard','Ordinary base / inexpensive card'],['premium','Better / premium card']],d.cardClass??'unknown')}</select></label>${field('Single-photo cutoff ($)','singlePhotoMax',dollars(d.singlePhotoMaxCents??500),{type:'number',min:0,step:'0.01'})}<label class="checkbox"><input name="memorabilia" type="checkbox" ${d.memorabilia?'checked':''}>Memorabilia / relic card</label></div><div class="note">${esc(photoRequirement(d).reason)}. ${missingPhotos(d).length?'Still needed: '+esc(missingPhotos(d).join(', '))+'.':'Required photos saved.'} Save changes to recalculate. A single photo does not establish reverse condition.</div>`;}
function editPriceButton(d){return d.id&&['draft','received'].includes(d.status)?`<button type="button" class="btn" data-price="${esc(d.id)}">${priceNeedsReview(d)?'Check price':'Edit price'}</button>`:'';}
let priceSnapshot=null;
function showPriceEditor(id){
 if(dirty){toast('Save your other changes first, then edit the price.');return;}
 const d=workspace.drafts.find(d=>d.id===id);if(!d||!['draft','received'].includes(d.status))return;
 const b=publication.batches.find(b=>b.status!=='cancelled'&&b.entries.some(e=>e.draftId===id));
 if(b){modal('Price in a saved eBay batch',`<p>${b.publicationApproved?'This batch has already been approved for publication. Check its eBay status before changing a live listing.':'Remove the saved batch from eBay batches first, then edit the price and prepare it again.'}</p><button class="btn" data-action="price-batches">Open eBay batches</button>`);return;}
 priceSnapshot={id,content:listingContent(d)};finishDirty=false;
 modal(priceNeedsReview(d)?'Check asking price':'Edit asking price',`<form id="price-form"><p><strong>${esc(d.title||d.sku)}</strong></p><p>Current asking price: ${askingMoney(d.askCents)}</p>${priceNeedsReview(d)?'<p class="batch-error">This saved price has not been confirmed separately from AI preparation. Check it before using it.</p>':''}<label class="field">Asking price ($)<input name="ask" type="number" inputmode="decimal" min="1" step="0.01" required value="${d.askCents==null?'':roundAskingCents(d.askCents)/100}"></label><p>Saving confirms this is the price you want to ask. It does not verify market value. Rounds to the nearest whole dollar. Changing the price requires reviewing this card again. This does not update a live eBay listing.</p><div class="actions"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary" data-write>Save price</button></div></form>`);
 $('#price-form [name="ask"]').focus();$('#price-form [name="ask"]').select();
}
async function savePrice(form){
 const d=workspace.drafts.find(d=>d.id===priceSnapshot?.id);if(!d||listingContent(d)!==priceSnapshot.content)throw Error('This card changed. Close and reopen the price editor.');
 const askCents=roundAskingCents(cents(new FormData(form).get('ask')));if(!Number.isSafeInteger(askCents)||askCents<100)throw Error('Enter an asking price of at least $1.');
 await save('/drafts/'+d.id,{askCents});finishDirty=false;close();render();toast('Price saved. Review this card again before listing.');
}
function priceFields(d={}){return `<div class="form-grid">${field('Acquisition cost ($)','cost',dollars(d.costCents),{type:'number',min:0,step:'0.01',help:'Total cost for this record. Blank means unknown.'})}${field('Asking price per unit ($)','ask',dollars(roundAskingCents(d.askCents)),{type:'number',min:0,step:'0.01',help:'Rounds to the nearest dollar when saved ($5.99 → $6).'})}${field('Acquired from','vendor',d.vendor,{placeholder:'Seller / collection'})}${field('Acquired date','acquiredDate',d.acquiredDate,{type:'date'})}${field('Purchase reference','acquisitionRef',d.acquisitionRef,{full:true})}</div>`;}
function editor(){const d=workspace.drafts.find(d=>d.id===selectedDraft)??{photos:[],kind:'comic'};if(d.status==='received')return receivedView(d);if(d.status==='archived')return archivedView(d);return `<button class="back" data-nav="intake">${icon('back')}Back to intake</button>${heading('SAVE IT NOW. FINISH IT WHEN YOU’RE READY.',d.id?'Intake details':'New intake',d.id?esc(d.sku):'A new draft stays outside your inventory counts.',editPriceButton(d))}<div class="editor-grid"><div class="sticky-panel"><section class="panel"><div class="panel-head"><h2>1 · Original photos</h2><span class="count">${d.photos.length} saved</span></div><div class="panel-body"><div class="photo-grid">${['front','back'].map(role=>{const p=d.photos.find(p=>p.role===role);return `<div><div class="photo-slot">${p?`<img src="/api/photos/${esc(p.id)}/preview" alt="${role} original preview">`:`${icon('camera')}<strong>Add ${role}</strong><small>Choose a photo<br>or use your camera</small><input type="file" data-photo="${role}" accept="image/jpeg,image/png,image/webp,image/heic" aria-label="Upload ${role} photo">`}</div><div class="photo-caption"><span>${role==='front'?'Front cover / face':'Back cover / reverse'}</span>${p?`<a href="/api/photos/${esc(p.id)}/original">Original</a>`:''}</div><div class="photo-tools">${p?`<label class="btn small file-choice">Replace ${role}<input type="file" data-photo="${role}" data-replace="${esc(p.id)}" accept="image/jpeg,image/png,image/webp,image/heic" aria-label="Replace ${role} photo"></label>`:`<label class="btn small file-choice">Take ${role} photo<input type="file" data-photo="${role}" accept="image/*" capture="environment" aria-label="Take ${role} photo"></label>`}</div></div>`;}).join('')}</div>${d.photos.length===2?'<button class="btn small swap-button" data-action="swap-photos" data-write>Swap front and back</button>':''}${photoHistory(d)}<div class="note">Your original stays unchanged. Previews are separate. Previous originals stay in photo history when replaced. JPEG and PNG work best; up to 12 MB each.</div></div></section><div class="note"><strong>Before you confirm:</strong> check the exact issue or card, printing, variant, and visible condition. AI suggestions need your review. Verify the exact card and visible condition before exporting.</div></div><form id="draft-form" class="panel"><div class="form-section"><h2 class="section-title"><span class="step">2</span>Identify the piece</h2><div class="form-error" role="alert"></div>${assessmentDetails(d)}${itemFields(d,true)}<div class="form-grid">${field('Team','team',d.team)}${field('Sport','sport',d.sport)}${conditionSelect('Listing condition','condition',d)}<label class="checkbox"><input type="checkbox" name="rookie" ${d.rookie?'checked':''}>Rookie card</label></div>${photoPolicyFields(d)}</div><div class="form-section"><h2 class="section-title">Price & acquisition</h2>${priceFields(d)}</div><div class="form-section"><h2 class="section-title">Condition & description</h2><div class="form-grid"><label class="field full">Visible condition notes<textarea name="conditionNotes" placeholder="Describe corners, spine, surface, creases, or other visible wear.">${esc(d.conditionNotes)}</textarea></label><label class="field full">Listing preparation text<textarea name="description" placeholder="Describe this exact piece. Avoid claims you have not verified.">${esc(d.description)}</textarea></label><label class="field full">Private notes<textarea name="notes" rows="2">${esc(d.notes)}</textarea></label></div></div><div class="form-actions"><small>${d.updatedAt?'Last saved '+esc(friendlyDate(d.updatedAt)):'Save a draft at any point.'}</small><div class="actions">${d.id?'<button type="button" class="btn danger" data-action="archive-draft" data-write>Archive</button>':''}<button type="submit" class="btn" data-write>Save draft</button><button type="button" class="btn primary" data-action="review-draft" data-write>Review intake ${icon('arrow')}</button></div></div></form></div>`;}
function receivedView(d){return `<button class="back" data-nav="intake">${icon('back')}Back to intake</button>${heading('INTAKE COMPLETE',esc(d.title),'Originals and reviewed details are saved.')}<section class="panel"><div class="panel-body">${pill('received')}<div class="review-photos">${d.photos.map(p=>`<img src="/api/photos/${esc(p.id)}/preview" alt="${esc(p.role)} photo">`).join('')}</div>${reviewDetails(d)}${photoHistory(d)}<div class="actions"><button class="btn primary" data-item="${esc(d.itemId)}">Open inventory record</button><a class="btn" href="/api/drafts/${esc(d.id)}/packet">Download preparation</a></div></div></section>`;}
function reviewDetails(d){return `<dl class="info-list">${[['Title',d.title||'Missing'],['SKU',d.sku],['Location',d.location||'Missing'],['Asking price',askingMoney(d.askCents)],['Acquisition cost',money(d.costCents)],['Type',d.kind],['Series / issue / year',[d.setName,d.number,d.year].filter(Boolean).join(' · ')||'Not recorded'],['Variant / serial',[d.parallel,d.serial].filter(Boolean).join(' · ')||'Not recorded'],['Player / character',d.subject||'Not recorded'],['Grade / certificate',[d.gradeCompany,d.grade,d.cert].filter(Boolean).join(' · ')||'Raw / not recorded'],['Autograph',d.autograph?'Verified autograph':'Not recorded'],['Acquisition',[d.vendor,d.acquiredDate,d.acquisitionRef].filter(Boolean).join(' · ')||'Not recorded']].map(([label,v])=>`<div><dt>${label}</dt><dd>${esc(v)}</dd></div>`).join('')}<div class="full"><dt>Visible condition</dt><dd>${esc(d.conditionNotes||'Missing')}</dd></div><div class="full"><dt>Description</dt><dd>${esc(d.description||'Not recorded')}</dd></div><div class="full"><dt>Private notes</dt><dd>${esc(d.notes||'None')}</dd></div></dl>`;}
function formItem(form){const f=new FormData(form),result={};for(const name of ['title','kind','location','subject','year','setName','number','parallel','serial','gradeCompany','grade','cert','notes','vendor','acquisitionRef','acquiredDate'])if(f.has(name))result[name]=String(f.get(name));result.autograph=f.has('autograph');result.costCents=cents(f.get('cost'));result.askCents=cents(f.get('ask'));return result;}
async function saveDraft(){const form=$('#draft-form');if(!form)return workspace.drafts.find(d=>d.id===selectedDraft);const data=formItem(form),f=new FormData(form);const current=workspace.drafts.find(d=>d.id===selectedDraft);if(current&&priceNeedsReview(current)&&roundAskingCents(data.askCents)===roundAskingCents(current.askCents))delete data.askCents;for(const k of ['team','sport','condition'])data[k]=String(f.get(k)??'');if(!data.condition&&conditionChoices(current??{}).legacy)data.condition=current.condition;data.rookie=f.has('rookie');data.description=String(f.get('description'));data.conditionNotes=String(f.get('conditionNotes'));data.photoPolicy=String(f.get('photoPolicy'));data.cardClass=String(f.get('cardClass'));data.singlePhotoMaxCents=cents(f.get('singlePhotoMax'));data.memorabilia=f.has('memorabilia');const result=await save('/drafts'+(selectedDraft&&selectedDraft!=='new'?'/'+selectedDraft:''),data);selectedDraft=result.draftId;dirty=false;return workspace.drafts.find(d=>d.id===selectedDraft);}
async function showReview(){const d=await saveDraft();render();if(missingPhotos(d).length)throw Error('Still needed: '+missingPhotos(d).join(', ')+'. '+photoRequirement(d).reason);modal('Review intake',`<p>Confirm the exact piece and visible condition, then add one physical unit to the Vault.</p><div class="review-photos">${d.photos.map(p=>`<img src="/api/photos/${esc(p.id)}/preview" alt="${esc(p.role)} photo">`).join('')}</div>${reviewDetails(d)}<div class="separator"></div><form id="review-form"><label class="checkbox"><input type="checkbox" name="identity" required>I checked the identity, year, number, and variant against the original photos.</label><br><label class="checkbox"><input type="checkbox" name="condition" required>${d.photos.some(p=>p.role==='back')?'I checked both sides and recorded the visible condition accurately.':'I checked the front and recorded visible condition. The unpictured reverse has not been assessed.'}</label><div class="note">This adds inventory here. It does not create or change a marketplace listing.</div><div class="actions"><button class="btn" type="button" data-action="close">Keep reviewing</button><button class="btn primary" type="submit" data-write>Confirm into Vault</button></div></form>`);}
function showCollx(key){const r=collx.rows.find(r=>r.key===key);if(r)modal('CollX details',collxDetail(r));}
function itemModal(id){const i=workspace.inventory.items.find(i=>i.id===id);if(!i)return;modal(i.title,`${reviewDetails({...i,conditionNotes:workspace.drafts.find(d=>d.itemId===id)?.conditionNotes})}<div class="separator"></div><div class="info-list"><div><small class="muted">Available units</small><p>${remaining(i)} / ${i.quantity}</p></div><div>${pill(itemStatus(i))}</div></div><div class="actions">${listCardButton(workspace.drafts.find(d=>d.itemId===i.id))}<button class="btn" data-edit="${esc(i.id)}">Edit record</button>${i.kind==='card'&&collx.rows.some(r=>r.itemId===i.id)?`<button class="btn" data-collx-card="${esc(collx.rows.find(r=>r.itemId===i.id).key)}">CollX details</button>`:''}${remaining(i)>0?`<button class="btn primary" data-sale="${esc(i.id)}">Record a sale</button>`:''}</div>`);}
function itemEditor(id){const d=workspace.inventory.items.find(i=>i.id===id)??{kind:'card',quantity:1,status:'intake',verification:'unverified'};modal(id?'Edit inventory':'Add inventory',`<form id="item-form" data-id="${esc(id??'')}">${itemFields(d)}<div class="separator"></div>${priceFields(d)}<div class="separator"></div><div class="form-grid">${field('SKU','sku',d.sku,{placeholder:'Leave blank to assign a Core SKU'})}${field('Physical quantity','quantity',d.quantity,{type:'number',min:1,step:1,required:true})}<label class="field">Status<select name="status">${options([['intake','In intake'],['ready','Ready to list'],['hold','Collection hold'],['listed','Listed · recorded']],d.status)}</select></label><label class="field">Verification<select name="verification">${options([['unverified','Not checked'],['verified','Physically verified'],['awaiting','Awaiting receipt']],d.verification)}</select></label><label class="field full">Private notes<textarea name="notes">${esc(d.notes)}</textarea></label></div><div class="note">A Core SKU identifies this record. Marketplace listing IDs are linked separately.</div><div class="actions"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary" data-write>Save inventory</button></div></form>`);}
function saleModal(id){const i=workspace.inventory.items.find(i=>i.id===id);modal('Record a sale',`<p>${esc(i.title)} · ${remaining(i)} units available. Enter the actual sale amounts; zeros mean no expense.</p><form id="sale-form" data-id="${esc(id)}"><div class="form-grid">${field('Units sold','quantity',1,{type:'number',min:1,step:1,required:true})}${field('Sale date','date',date(),{type:'date',required:true})}${[['Item revenue ($)','revenueCents'],['Shipping collected ($)','shippingCollectedCents'],['Selling fees ($)','sellingFeeCents'],['Promotion fees ($)','promoFeeCents'],['Postage paid ($)','postageCents'],['Packing supplies ($)','suppliesCents'],['Refund amount ($)','refundCents']].map(([label,name])=>field(label,name,'0.00',{type:'number',min:0,step:'0.01',required:true})).join('')}${field('Sales channel','channel','eBay',{required:true})}${field('Order reference','reference','')}${field('Notes','notes','',{full:true})}</div><div class="note">Records the sale in BTCore only. It does not update, end, or refund a listing on any marketplace.</div><div class="actions"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary" data-write>Record sale</button></div></form>`);}
const eventLabel={'item.created':'Added inventory','item.updated':'Updated inventory','sale.recorded':'Recorded a sale','sale.voided':'Reversed a recorded sale','core.card-prepared':'Prepared card details','core.listing-approved':'Reviewed listing details','core.collx-price-saved':'Saved independent CollX price','core.collx-observation-saved':'Recorded CollX listing check','core.draft-saved':'Saved intake details','core.photo-saved':'Saved an original photo','core.intake-confirmed':'Confirmed intake into the Vault','core.photo-replaced':'Replaced a photo; previous original kept','core.photos-swapped':'Corrected front and back assignments','core.draft-archived':'Archived unfinished intake','core.draft-restored':'Restored intake for review'};
function activity(){const events=workspace.inventory.events.slice(-35).reverse(),sales=workspace.inventory.sales.slice(-10).reverse();return `${heading('A CLEAR RECORD','Activity','Your saved changes, intake progress, and recorded sales.',`<a class="btn" href="/api/export/sales.csv">${icon('download')}Export sales</a>`)}<div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Recent activity</h2><span class="count">${events.length}</span></div>${events.length?`<div class="activity">${events.map(e=>{const entity=workspace.inventory.items.find(i=>i.id===e.entityId)??workspace.drafts.find(d=>d.id===e.entityId);return `<div class="activity-row"><span class="activity-dot"></span><div><strong>${esc(eventLabel[e.action]??e.action)}</strong><small>${esc(entity?.title||entity?.sku||'Workspace')} · ${esc(friendlyDate(e.at))}</small></div></div>`;}).join('')}</div>`:empty('Nothing recorded yet.','Your next saved change will appear here.')}</section><section class="panel"><div class="panel-head"><h2>Recorded sales</h2><strong>${stats.sales}</strong></div>${sales.length?sales.map(s=>`<div class="queue-item"><div class="queue-info"><strong>${esc(workspace.inventory.items.find(i=>i.id===s.itemId)?.title)}</strong><small>${esc(s.date)} · ${s.quantity} units · ${money(s.revenueCents)}${s.voidedAt?' · reversed':''}</small></div>${!s.voidedAt?`<button class="text-btn" data-reverse="${esc(s.id)}">Correct</button>`:''}</div>`).join(''):empty('Sales will appear here.','Open an inventory record to record a sale.')}</section></div>`;}
function settings(){return `${heading('YOUR WORKSPACE','Settings',session.loginRequired===false?'Keep your workspace and records in your control.':'Keep your account and records in your control.')}<div class="settings-grid">${session.loginRequired===false?'<section class="panel"><div class="panel-head"><h2>Workspace access</h2></div><div class="panel-body"><h3>Open and ready.</h3><p>No account or password is needed right now. Open this address on any of your devices to continue.</p><div class="note">Anyone with this address can view and edit this workspace while sign-in is off.</div></div></section>':`<section class="panel"><div class="panel-head"><h2>Account</h2>${pill('Owner')}</div><div class="panel-body"><p>Signed in as <strong>${esc(session.email)}</strong>.</p><form id="password-form"><div class="form-error" role="alert"></div><div class="form-grid">${field('Current password','currentPassword','',{type:'password',required:true,full:true})}${field('New password','newPassword','',{type:'password',required:true,full:true,help:'Use at least 12 characters.'})}</div><br><button class="btn" type="submit" data-write>Change password</button></form></div></section>`}<section class="panel"><div class="panel-head"><h2>Backups & exports</h2>${icon('download').replace('<svg','<svg width="17" height="17"')}</div><div class="panel-body"><p>Download a complete workspace backup with the unchanged original photos. Keep a copy somewhere separate.</p><a class="btn primary" href="/api/backup">${icon('download')}Download full backup</a><div class="separator"></div><div class="actions"><a class="btn" href="/api/export/inventory.csv">Inventory CSV</a><a class="btn" href="/api/export/sales.csv">Sales CSV</a></div><div class="note">Backups are manual in this development release. Recovery is available through the included operator restore command.</div></div></section><section class="panel"><div class="panel-head"><h2>Development workspace</h2><button class="btn" data-nav="mirror">Side-by-side trial</button></div><div class="panel-body"><div class="status-row"><span>Inventory & intake</span><strong>Available</strong></div><div class="status-row"><span>Photo allowance used</span><strong>${storageSize(photoStorage.usedBytes)} / ${storageSize(photoStorage.limitBytes)}</strong></div><div class="status-row"><span>AI identification</span><strong>${ai?.configured?'Connected':'Not configured'}</strong></div><div class="status-row"><span>AI usage this month</span><strong>${money(Math.ceil((ai?.usage?.chargedMicros??0)/10000))} / ${money((ai?.monthlyBudgetMicros??10000000)/10000)}</strong></div><div class="status-row"><span>eBay publishing</span><strong>${publication.connection?.connected?'Connected on this device':publication.enabled?'Connection available':'Not configured'}</strong></div><div class="status-row"><span>CollX posting & automatic delisting</span><strong>Not connected</strong></div><div class="note">Inventory edits stay in Core. eBay publication requires a separate reviewed approval. Marketplace sales sync and automatic delisting are not connected.</div></div></section><section class="panel"><div class="panel-head"><h2>Use it on your phone</h2></div><div class="panel-body"><h3>Your collecting desk, wherever you are.</h3><p>${session.loginRequired===false?'Open this same address in Safari.':'Open this same address in Safari and sign in with your BTCore account.'} Use Share → Add to Home Screen for a dedicated app shortcut.</p><div class="note">An internet connection is required to save changes. If a save fails, your open form remains available so you can retry.</div></div></section></div>`;}
function loginScreen(){const setup=session.setupRequired;$('#app').innerHTML=`<main id="main" class="login"><section class="login-art"><div class="brand">${brand}</div><div><div class="eyebrow">BALLARD TRADING CO.</div><h1>Good pieces.<br><em>Better organized.</em></h1><p>Your cards, comics, and next great finds. One private workspace that goes where you do.</p></div><footer>BUILT FOR THE WAY WE COLLECT.</footer></section><section class="login-form"><div class="login-box"><div class="eyebrow">${setup?'YOUR OWN WORKSPACE':'WELCOME BACK'}</div><h2>${setup?'Set up BTCore.':'Back to the collection.'}</h2><p>${setup?'Use your private setup code to create the owner account.':'Sign in to pick up right where you left off.'}</p><div class="form-error" role="alert"></div><form id="auth-form">${setup?field('Private setup code','setupCode','',{type:'password',required:true}):''}${field('Email address','email','',{type:'email',required:true})}${field(setup?'Create a password':'Password','password','',{type:'password',required:true,help:setup?'At least 12 characters.':''})}<button class="btn primary" type="submit" data-write>${setup?'Create owner account':'Sign in'} ${icon('arrow')}</button></form><p class="login-foot">Private access · BTCore v0.7.4</p></div></section></main>`;}
async function boot(){try{session=await api('/session');if(!session.authenticated)return loginScreen();await load();if(['#inventory','#intake','#publication','#collx','#mirror'].includes(location.hash))view=location.hash.slice(1);if(view==='mirror')mirrorReport=await api('/mirror');render();const pendingId=sessionStorage.getItem(pendingListingKey);if(['intake','publication'].includes(view)&&pendingId)await run(()=>continueListingFlow(pendingId));}catch(e){$('#app').innerHTML=`<main id="main" class="error-page"><div class="brand">${brand}</div><h1>We couldn’t open the workspace.</h1><p>${esc(e.message)}</p><button class="btn" data-action="boot">Try again</button></main>`;}}
document.addEventListener('submit',e=>{
 const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();run(async()=>{
  if(form.id==='cdp-date-form'){cdpImport.observedAt=new Date(new FormData(form).get('observedAt')).toISOString();const report=await api('/inventory/import/preview',{method:'POST',data:{data:cdpImport}});cdpImportRevision=report.revision;modal('Review inventory migration',`<p>${report.rows} source rows · ${report.created} new records · ${report.enriched} enriched · ${report.unchanged} unchanged</p><p>Master SKUs, existing costs and locations are protected. Missing and conflicting locations stay flagged.</p><p>${report.exceptions.length} issues. All issues remain available after import.</p>${report.exceptions.slice(0,30).map(x=>`<p>${esc(x.sku)}: ${esc(x.reason)}</p>`).join('')}<button class="btn primary" data-action="cdp-import-confirm">Import inventory</button>`);return;}
  if(form.id==='bulk-row-form'){await saveBulkEditor(form);return;}
  if(form.matches('[data-quick-edit]')){if(form.dataset.attentionRow){await saveDeskFixes([form.dataset.quickEdit]);return;}captureDeskInputs();await saveQuickRows([form.dataset.quickEdit]);render();return;}
  if(form.getAttribute('id')==='mirror-import-form'){
   const fields=Object.fromEntries(new FormData(form));mirrorImport=mappedExport(mirrorCSV,fields,fields);
   modal('Review comparison import',`<p>${mirrorImport.records.length} ${esc(mirrorImport.source)} records observed ${esc(mirrorImport.observedAt)}. Confirm these are the intended columns and date.</p>${mirrorImport.records.slice(0,10).map(r=>`<p>${esc(r.id)} · ${esc(r.sku)} · ${esc(r.title)} · ${money(r.priceCents)} · Qty ${r.quantity??'unknown'} · eBay ${esc(r.ebayId||'unlinked')} · CollX ${esc(r.collxId||'unlinked')}</p>`).join('')}<p>All rows are validated together. No physical stock, target prices or marketplace listings change.</p><button class="btn primary" data-action="mirror-import-confirm">Save comparison records</button>`);return;
  }
  if(form.getAttribute('id')==='collx-search-form'){const f=new FormData(form);collxQuery=String(f.get('query'));collxFilter=String(f.get('filter'));collxPageNumber=1;render();return;}
  if(form.getAttribute('id')==='collx-price-form'||form.getAttribute('id')==='collx-observation-form'){
   const f=new FormData(form),key=form.dataset.key,data={key,fingerprint:form.dataset.fingerprint,priceCents:cents(f.get('price'))};
   if(form.getAttribute('id')==='collx-observation-form')Object.assign(data,{externalId:String(f.get('externalId')),url:String(f.get('url')),status:String(f.get('status')),checked:f.has('checked')});
   await save(form.getAttribute('id')==='collx-price-form'?'/collx/price':'/collx/observation',data);finishDirty=false;render();showCollx(key);toast(form.getAttribute('id')==='collx-price-form'?'CollX price saved in Core.':'CollX observation saved.');return;
  }
  if(form.getAttribute('id')==='price-form'){await savePrice(form);return;}
  if(form.getAttribute('id')==='listing-flow-form'){await saveListingFlow(form);return;}
  if(form.getAttribute('id')==='finish-form'){await saveFinishDetails(form);return;}
  if(form.getAttribute('id')==='auth-form'){const input=Object.fromEntries(new FormData(form));await api(session.setupRequired?'/setup':'/login',{method:'POST',data:input});await boot();return;}
  if(form.getAttribute('id')==='draft-form'){await saveDraft();render();toast('Intake saved. Pick it up whenever you’re ready.');return;}
  if(form.getAttribute('id')==='review-form'){await save('/drafts/'+selectedDraft,{identityReviewed:true,conditionReviewed:true});const result=await save('/drafts/'+selectedDraft+'/receive',{});close();view='inventory';selectedDraft=null;render();itemModal(result.itemId);toast('Confirmed into the Vault.');return;}
  if(form.getAttribute('id')==='item-form'){const f=new FormData(form),data=formItem(form);Object.assign(data,{sku:String(f.get('sku')),quantity:Number(f.get('quantity')),status:String(f.get('status')),verification:String(f.get('verification'))});const result=await save('/items'+(form.dataset.id?'/'+form.dataset.id:''),data);dirty=false;close();render();itemModal(result.itemId);toast('Inventory saved.');return;}
  if(form.getAttribute('id')==='sale-form'){const f=Object.fromEntries(new FormData(form));for(const key of Object.keys(f))if(key.endsWith('Cents'))f[key]=cents(f[key]);f.quantity=Number(f.quantity);f.itemId=form.dataset.id;await save('/sales',f);close();render();toast('Sale recorded.');return;}
  if(form.getAttribute('id')==='password-form'){const result=await api('/password',{method:'POST',data:Object.fromEntries(new FormData(form))});session.csrf=result.csrf;form.reset();toast('Password changed. Other sessions have been signed out.');}
 });
});
document.addEventListener('input',e=>{if(e.target.closest('#desk-shipping'))captureDeskInputs();trackQuickEdit(e.target);if(e.target.closest('#collx-price-form,#collx-observation-form'))finishDirty=true;if(e.target.closest('#price-form,#listing-flow-form,#bulk-row-form'))finishDirty=true;if(e.target.closest('#finish-form')&&!e.target.matches('[data-finish-photo]')){finishDirty=true;updateFinishStatus();}if(e.target.closest('#draft-form')){dirty=true;const label=$('.connection');if(label)label.textContent='Unsaved details';}});
document.addEventListener('change',e=>{
 if(e.target.matches('[data-desk-photo]')&&e.target.files[0]){const input=e.target,file=input.files[0],id=input.dataset.deskPhoto,original=workspace.drafts.find(d=>d.id===id),content=listingContent(original);run(async()=>{if(file.size>12*1024*1024)throw Error('Use an original 12 MB or smaller.');await load();if(listingContent(workspace.drafts.find(d=>d.id===id))!==content||quickEdits.has(id)&&quickEdits.get(id).content!==content)throw Error('This card changed. Save or review its edits before adding a photo.');await uploadPhoto(id,input.dataset.role,file);if(quickEdits.has(id))quickEdits.get(id).content=listingContent(workspace.drafts.find(d=>d.id===id));render();toast('Photo saved. Continue the remaining fields here.');});return;}
 if(e.target.closest('#desk-shipping'))captureDeskInputs();
 if(e.target.matches('[data-edit-select]')){const id=e.target.dataset.editSelect;if(e.target.checked){if(bulkSelection.size>=500){e.target.checked=false;toast('Select up to 500 cards at a time.');return;}bulkSelection.add(id);}else bulkSelection.delete(id);updateQuickBar();return;}
 if(e.target.closest('#bulk-row-form'))finishDirty=true;
 if(e.target.closest('[data-quick-edit]'))trackQuickEdit(e.target);
 if(e.target.id==='inventory-cdp-csv'&&e.target.files[0]){const file=e.target.files[0];run(async()=>{if(file.size>10*1024*1024)throw Error('Choose a CSV under 10 MB.');const csv=parseCSV(await file.text());cdpImport={rows:csv.rows.map(r=>Object.fromEntries(csv.headers.map((h,n)=>[h,r[n]])))};modal('Date of CDP export','<form id="cdp-date-form"><label class="field">Export observed at (your local time)<input name="observedAt" type="datetime-local" required></label><button class="btn primary">Preview migration</button></form>');});return;}
 if(['mirror-csv','mirror-json'].includes(e.target.id)&&e.target.files[0]){const file=e.target.files[0],kind=e.target.id;run(async()=>{if(file.size>10*1024*1024)throw Error('Choose a file under 10 MB.');const raw=await file.text();if(kind==='mirror-csv'){mirrorCSV=parseCSV(raw);modal('Map comparison export',mappingForm(mirrorCSV));}else{const data=JSON.parse(raw);if(data.source!=='btconnect-ebay-baseline')throw Error('Choose a captured eBay baseline.');await save('/mirror/import',data);mirrorReport=await api('/mirror');render();toast('eBay baseline saved. Scheduled sync is still off.');}});return;}

 if(e.target.closest('#collx-observation-form'))finishDirty=true;
 if(e.target.matches('[data-finish-photo]')&&e.target.files[0]){const input=e.target,file=input.files[0],id=input.dataset.finishPhoto;run(async()=>{if(file.size>12*1024*1024)throw Error('Use an original 12 MB or smaller.');await load();const d=workspace.drafts.find(d=>d.id===id);if(!d||listingContent(d)!==finishSnapshots.get(id))throw Error('This card changed. Reopen the batch editor before uploading.');await uploadPhoto(id,input.dataset.role,file);finishSnapshots.set(id,listingContent(workspace.drafts.find(d=>d.id===id)));input.closest('label').hidden=true;updateFinishStatus();toast('Photo saved. Your entered prices and conditions are still here.');});return;}

 if(e.target.matches('#prep-filter')){prepFilter=e.target.value;render();return;}
 if(e.target.matches('[data-review-card]')){if(e.target.checked){if(selectedListings.size>=500){e.target.checked=false;toast('Approve up to 500 cards at a time.');return;}selectedListings.set(e.target.dataset.reviewCard,listingContent(workspace.drafts.find(d=>d.id===e.target.dataset.reviewCard)));}else selectedListings.delete(e.target.dataset.reviewCard);updatePreparationSelection();return;}
 if(e.target.id==='batch-kind'){renderBatchProgress();return;}
 if(['batch-files','batch-single-files'].includes(e.target.id)){try{const files=[...e.target.files];const total=files.reduce((sum,file)=>sum+file.size,0);if(total+batch.pendingBytes>photoStorage.limitBytes-photoStorage.usedBytes)throw Error(`These photos need ${storageSize(total+batch.pendingBytes)}; ${storageSize(photoStorage.limitBytes-photoStorage.usedBytes)} remains. Your current queue is unchanged.`);if(e.target.id==='batch-single-files'&&$('#batch-kind').value!=='card')throw Error('Front-only intake is for cards.');batch.addFiles(files,e.target.id==='batch-single-files'?'single':'paired');e.target.value='';$('#main .form-error').textContent='';}catch(err){error(err);}return;}
 if(!e.target.matches('[data-photo]')||!e.target.files[0])return;
 const file=e.target.files[0],role=e.target.dataset.photo,replacement=e.target.dataset.replace;
 run(async()=>{if(file.size>12*1024*1024)throw Error('Use an original 12 MB or smaller.');const d=await saveDraft();await uploadPhoto(d.id,role,file,replacement);render();toast(replacement?'Photo replaced. Previous original kept; review both sides again.':`${role==='front'?'Front':'Back'} original saved and verified.`);});
});
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a[data-action]');if(!b)return;
 if(b.dataset.mirrorPage){mirrorPageNumber=Number(b.dataset.mirrorPage);render();window.scrollTo(0,0);return;}
 if(b.dataset.collxCard){if(finishDirty&&!confirm('Discard unsaved CollX details?'))return;finishDirty=false;showCollx(b.dataset.collxCard);return;}
 if(b.dataset.collxObserve){if(finishDirty&&!confirm('Discard unsaved CollX details?'))return;finishDirty=false;const r=collx.rows.find(r=>r.key===b.dataset.collxObserve);if(r)modal('Record CollX listing',collxObservationForm(r));return;}
 if(b.dataset.collxPage){collxPageNumber=Number(b.dataset.collxPage);render();window.scrollTo(0,0);return;}
 if(b.dataset.collxDraft){if(finishDirty&&!confirm('Discard unsaved CollX details?'))return;finishDirty=false;close();view='intake';selectedDraft=b.dataset.collxDraft;render();return;}
 if(b.dataset.collxItem){if(finishDirty&&!confirm('Discard unsaved CollX details?'))return;finishDirty=false;itemModal(b.dataset.collxItem);return;}
 if(b.dataset.price){showPriceEditor(b.dataset.price);return;}
 if(b.hasAttribute('data-list-card')){run(async()=>{await showListingFlow(b.dataset.listCard||null);});return;}
 if(b.dataset.intakeFilter){draftFilter=b.dataset.intakeFilter;render();return;}
 if(b.dataset.batchRemove){batch.remove(b.dataset.batchRemove);return;}
 if(b.dataset.batchSwap){batch.swap(b.dataset.batchSwap);return;}
 if(b.dataset.nav){navigate(b.dataset.nav);return;}
 if(b.dataset.draft){if(!confirmLeave())return;view='intake';selectedDraft=b.dataset.draft;dirty=false;render();window.scrollTo(0,0);return;}
 if(b.dataset.item){itemModal(b.dataset.item);return;}if(b.dataset.edit){itemEditor(b.dataset.edit);return;}if(b.dataset.sale){saleModal(b.dataset.sale);return;}
 if(b.dataset.reverse){modal('Correct this sale?',`<p>Reversing this record restores its units and cost in BTCore. The original sale remains in the history. No refund or marketplace change is made.</p><div class="actions"><button class="btn" data-action="close">Cancel</button><button class="btn danger" data-action="reverse-sale" data-id="${esc(b.dataset.reverse)}" data-write>Reverse record</button></div>`);return;}
 const action=b.dataset.action;if(!action)return;
 if(action?.startsWith('desk-')){run(()=>deskAction(action,b));return;}
 if(action==='quick-select-all'){for(const id of shownEditIds()){if(bulkSelection.size>=500)break;bulkSelection.add(id);}updateQuickBar();return;}
 if(action==='quick-clear-selection'){bulkSelection.clear();updateQuickBar();return;}
 if(action==='quick-bulk-edit'){run(async()=>showBulkEditor());return;}
 if(action==='quick-discard'){run(async()=>{quickEdits.delete(b.dataset.rowId);await load();render();});return;}
 if(action==='quick-save-all'){run(async()=>{await saveQuickRows();render();});return;}
 if(action?.startsWith('mirror-')){run(async()=>{
  if(action==='mirror-sync'){toast('Collecting all eBay listing and order pages…');await api('/mirror/sync',{method:'POST',data:{}});await load();}
  if(action==='mirror-stop')await api('/mirror/stop',{method:'POST',data:{}});
  if(action==='mirror-import-confirm'){await save('/mirror/import',mirrorImport);mirrorImport=null;close();}
  mirrorReport=await api('/mirror');render();toast(action==='mirror-sync'?'eBay mirrored. Read-only sync runs for three weeks.':action==='mirror-stop'?'Scheduled sync stopped. Saved observations kept.':'Comparison updated.');
 });return;}
 if(action==='cdp-import-confirm'){run(async()=>{if(workspace.revision!==cdpImportRevision)throw Error('The inventory changed. Preview the import again.');await save('/inventory/import/cdp',cdpImport);cdpImport=null;close();view='inventory';render();toast('CDP inventory imported. Review location issues before fulfillment.');});return;}
 if(action==='location-audit'){run(async()=>{const r=await api('/inventory/locations');modal('Location issues',`<p>${r.total} records · ${r.missing.length} missing · ${r.partial.length} partial / unstructured · ${r.conflicts.length} conflicts · ${r.duplicateIdentifiers.length} duplicate identifiers</p><a class="btn" href="/api/inventory/locations" target="_blank" rel="noopener">Open complete audit</a>${[...r.conflicts,...r.missing,...r.partial].slice(0,100).map(i=>`<p>${esc(i.sku)} · ${esc(i.title)} · ${esc(i.location||'LOCATION MISSING')}</p>`).join('')}`);});return;}
 if(action==='batch-intake'){if(!confirmLeave())return;dirty=false;view='batch';render();return;}
 if(action==='batch-start'){run(async()=>{const kind=$('#batch-kind').value;if(kind!=='card'&&batch.items.some(i=>i.files.length===1))throw Error('Front-only groups require Trading cards. Remove those groups or change the type.');const details={kind,location:$('#batch-location').value,photoPolicy:kind==='card'?'value-based':'two-sided',cardClass:'unknown',singlePhotoMaxCents:cents($('[name="batchCutoff"]').value)};if(details.singlePhotoMaxCents===null)throw Error('Enter a single-photo cutoff.');await batch.start(details);if(!batch.unfinished&&details.kind==='card'&&ai?.configured){await save('/preparation/start',{ids:batch.items.map(i=>i.draftId)});view='prepare';render();toast('Photos saved. Card preparation is running.');}});return;}
 if(action==='batch-pause'){batch.pause();return;}
 if(action==='batch-clear'){if(!batch.unfinished||confirm('Clear the photos waiting in this tab? Any saved drafts and originals stay in Intake.')){batch.clear();render();}return;}
 if(action==='prepare-view'){navigate('prepare');return;}
 if(action==='fill-missing'){fillMissingDetails();return;}
 if(action?.startsWith('ebay-')){run(()=>ebayAction(action,b.dataset.batchId));return;}
 if(action==='stage-publication'){showPublicationReview();return;}
 if(action==='finish-remaining'){showFinishDetails();return;}
 if(action==='price-batches'){close();navigate('publication');return;}
 if(action==='edit-batch'){showFinishDetails(true);return;}
 if(action==='select-ready'){selectedListings=new Map(readyListings().slice(0,500).map(d=>[d.id,listingContent(d)]));updatePreparationSelection();return;}
 if(action==='clear-listings'){selectedListings.clear();updatePreparationSelection();return;}
 if(action==='close'){close();return;}if(action==='new-item'){itemEditor();return;}if(action==='new-draft'){if(!confirmLeave())return;view='intake';selectedDraft='new';dirty=false;render();return;}
 if(action==='previous'||action==='next'){page+=action==='next'?1:-1;renderTable();return;}
 run(async()=>{
  if(action==='prepare-all'){
   const ids=preparationNeeded.slice(0,500);
   if(!ids.length){view='prepare';render();return;}await load();const result=await save('/preparation/start',{ids,retry:true});view='prepare';render();toast(`${result.queued} cards queued. You can leave this page while they prepare.`);
  }
  if(action==='save-publication'){const ids=[...document.querySelectorAll('[data-stage-card]:checked')].map(x=>x.dataset.stageCard);const entries=await Promise.all(publicationSelection.filter(e=>ids.includes(e.id)).map(async e=>({id:e.id,fingerprint:await contentFingerprint(e.content)})));await save('/publication/batches',{entries});close();view='publication';render();toast('Batch saved. Nothing has been published to eBay.');}
  if(action==='cancel-publication'){await save('/publication/cancel',{id:b.dataset.batchId});render();toast('Batch removed from the queue. Cards and photos are unchanged.');}
  if(action==='prepare-one'){await saveDraft();await save('/preparation/start',{ids:[selectedDraft],retry:true});render();toast('Card queued for preparation.');}
  if(action==='review-listings'){
   reviewSelection=workspace.drafts.filter(d=>selectedListings.has(d.id)).map(d=>({id:d.id,content:selectedListings.get(d.id)}));if(!reviewSelection.length)throw Error('Select cards to approve.');
   modal('Approve card details',`<p>Approve <strong>${reviewSelection.length} selected cards</strong> for listing preparation.</p><p>By approving, you confirm you checked their identities, prices, visible condition, and photos. Their images will be available through the export links.</p><div class="note">Cards needing attention are excluded from Select all ready. Publishing requires the final eBay review; this does not mark cards sold.</div><div class="actions"><button class="btn" data-action="close">Keep reviewing</button><button class="btn primary" data-action="approve-listings" data-write>Confirm approval of ${reviewSelection.length} ${reviewSelection.length===1?'card':'cards'}</button></div>`);
  }
  if(action==='approve-listings'){const entries=await Promise.all(reviewSelection.map(async({id,content})=>({id,fingerprint:[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(content)))].map(n=>n.toString(16).padStart(2,'0')).join('')})));await load();const result=await save('/preparation/approve',{entries});selectedListings.clear();close();render();toast(`${result.approved} cards approved. Ready for marketplace review.`);}
  if(action==='swap-photos'){await saveDraft();await save('/drafts/'+selectedDraft+'/swap-photos',{});render();toast('Front and back swapped. Review both sides again.');}
  if(action==='archive-draft'){await saveDraft();render();modal('Archive this intake?',`<p>The draft and every original stay saved. Restore it from the Archived tab whenever you need it.</p><div class="actions"><button class="btn" data-action="close">Keep working</button><button class="btn danger" data-action="confirm-archive" data-write>Archive intake</button></div>`);}
  if(action==='confirm-archive'){await save('/drafts/'+selectedDraft+'/archive',{});close();selectedDraft=null;render();toast('Intake archived. Photos and details kept.');}
  if(action==='restore-draft'){await save('/drafts/'+selectedDraft+'/restore',{});draftFilter='draft';render();toast('Intake restored. Review it again before confirming.');}
  if(action==='review-draft')await showReview();
  if(action==='reverse-sale'){await save('/sales/'+b.dataset.id+'/reverse',{});close();render();toast('Sale reversed; history preserved.');}
  if(action==='reload'){if(!confirmLeave())return;await load();if(view==='mirror')mirrorReport=await api('/mirror');dirty=false;render();toast('Workspace refreshed.');}
  if(action==='logout'){if(!confirmLeave())return;if(batch.unfinished&&!confirm('Sign out and clear photos waiting in this tab? Saved drafts stay in Intake.'))return;batch.clear();await api('/logout',{method:'POST'});workspace=null;dirty=false;view='home';await boot();}
  if(action==='boot')await boot();
 });
});
let preparationPollRunning=false;
setInterval(async()=>{if(preparationPollRunning||document.hidden||!session?.authenticated||busy||dirty||quickEdits.size||selectedDraft||$('#modal[open]')||!['intake','prepare','home'].includes(view)||!workspace.drafts.some(d=>['queued','running'].includes(d.preparation?.status)))return;preparationPollRunning=true;try{await load();if(!busy&&!dirty&&!quickEdits.size&&!selectedDraft&&!$('#modal[open]')&&!document.hidden)render();}catch{}finally{preparationPollRunning=false;}},4000);
window.addEventListener('beforeunload',e=>{if(dirty||finishDirty||quickEdits.size||batch.unfinished){e.preventDefault();e.returnValue='';}});
boot();

function preparationBanner(){const cards=preparationCards();if(!cards.length)return '';const active=cards.filter(d=>['queued','running'].includes(d.preparation?.status)).length;return `<section class="prep-banner"><div><h2>${active?`${active} cards preparing`:'Turn your photos into listings'}</h2><p>${active?'Preparation continues when you leave this screen.':'Identify cards and collect price references. You choose and confirm each asking price.'}</p></div><div class="actions"><button class="btn primary" data-action="prepare-all" data-write ${ai?.configured?'':'disabled'}>Prepare cards</button><button class="btn" data-action="prepare-view">Review & export</button></div>${!ai?.configured?'<p>AI connection is being configured. Your photos are saved.</p>':''}</section>`;}
function priceResearch(d){
 const r=d.preparation?.result;if(!r)return '';
 const basis={sold:'Reported sale references — check the links',asking:'Active asking prices — not sales',estimate:'AI estimate — not verified market value',unknown:'No supported price recommendation'}[r.priceBasis]??'Unverified research';
 return `<div class="price-research"><strong>AI price research</strong><p>${r.askCents==null?'No suggestion':`Suggestion: ${askingMoney(r.askCents)}`} · ${esc(basis)}</p><p>Research is separate from your asking price. ${r.pricingEvidenceVersion===1?'Comparison details were extracted by AI and still need your check.':'Older research has not passed the new exact-card evidence checks.'}</p><details><summary>Research explanation and sale references</summary><p>${esc(r.priceReason)}</p>${(r.soldComparisons??[]).filter(c=>/^https:\/\//.test(c.url)).map(c=>`<p><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">${esc(c.title)}</a><br>${esc(c.soldDate)} · Item ${money(c.priceCents)} · ${c.shippingCents==null?'Shipping unknown':`Shipping ${money(c.shippingCents)}`}<br>${esc([c.identity?.year,c.identity?.setName,c.identity?.subject,c.identity?.number,c.identity?.parallel,c.identity?.gradeCompany,c.identity?.grade,c.identity?.printRun?'Print run '+c.identity.printRun:''].filter(Boolean).join(' · '))}</p>`).join('')||'<p>No structured exact-card sold comparisons saved.</p>'}</details></div>`;
}
function assessmentDetails(d){const p=d.preparation,r=p?.result;if(!r)return `<div class="note">${esc(p?.error??(p?.status==='queued'?'Queued for preparation.':p?.status==='running'?'Preparing this card…':'Use AI to prepare details from the saved photos.'))}${d.id&&selectedDraft===d.id&&ai?.configured&&!['running','queued'].includes(p?.status)?'<br><button type="button" class="btn small" data-action="prepare-one" data-write>Prepare this card</button>':''}</div>`;return `<details class="assessment" open><summary>Assessment · ${esc(r.confidence)} confidence</summary><p>${esc(r.identityNotes)}</p>${priceResearch(d)}${r.warnings?.length?`<ul>${r.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${r.sources?.length?`<ul>${r.sources.filter(x=>/^https:\/\//.test(x.url)).map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a><small>${esc(x.note)}</small></li>`).join('')}</ul>`:''}${selectedDraft===d.id&&ai?.configured?'<button type="button" class="btn small" data-action="prepare-one" data-write>Prepare again after corrections</button>':''}<small>Prepared ${esc(friendlyDate(p.completedAt))}. Estimates and asking prices are not verified sold comps.</small></details>`;}
function preparationCards(){const rank=d=>approvedListings.has(d.id)?3:['queued','running'].includes(d.preparation?.status)?2:listingProblems(d).length?1:0;return workspace.drafts.filter(d=>d.kind==='card'&&d.status!=='archived'&&d.photos.length).sort((a,b)=>rank(a)-rank(b));}
function readyListings(){return preparationCards().filter(d=>!approvedListings.has(d.id)&&!listingProblems(d).length);}
function updatePreparationSelection(){
 document.querySelectorAll('[data-review-card]').forEach(input=>{input.checked=selectedListings.has(input.dataset.reviewCard);});
 const count=selectedListings.size,ready=readyListings().length;
 const summary=$('#prep-selection-count');if(summary)summary.textContent=`${count} selected`;
 const approve=$('[data-action="review-listings"]');if(approve){approve.textContent=`Approve selected (${count})`;approve.disabled=count===0;}
 const edit=$('[data-action="edit-batch"]');if(edit)edit.textContent=count?`Edit selected (${count})`:'Edit batch';
 const clear=$('[data-action="clear-listings"]');if(clear)clear.disabled=count===0;
 const all=$('[data-action="select-ready"]');if(all){all.textContent=ready>500?'Select next 500 ready':`Select all ready (${ready})`;all.disabled=ready===0;}
}
function preparationStatus(d){return approvedListings.has(d.id)?'approved':['queued','running'].includes(d.preparation?.status)?'preparing':listingProblems(d).length?'attention':'ready';}
function preparationView(){
 const cards=preparationCards(),active=cards.filter(d=>['queued','running'].includes(d.preparation?.status)).length,ready=readyListings().length,attention=cards.filter(d=>!approvedListings.has(d.id)&&listingProblems(d).length&&!['queued','running'].includes(d.preparation?.status)).length;
 return `<button class="back" data-nav="intake">${icon('back')}Back to intake</button>${heading('FROM PHOTOS TO LISTINGS','Review your cards',`${ready} ready for approval · ${attention} need attention · ${active} preparing`,`${finishCards().some(d=>listingProblems(d).length)?`<button class="btn primary" data-action="finish-remaining">Finish remaining (${finishCards().filter(d=>listingProblems(d).length).length})</button>`:''}<button class="btn" data-action="prepare-all" data-write ${ai?.configured&&preparationNeeded.length?'':'disabled'}>Prepare remaining cards</button><button class="btn" data-nav="publication">eBay listings</button><button class="btn" data-nav="collx">CollX</button>${approvedListings.size?'<a class="btn primary" href="/api/export/cdp.csv">Download CDP CSV</a>':''}`)}<div class="form-error" role="alert"></div><p class="prep-guidance">${!ready&&attention?'Use Check price on a card to confirm its asking price. Use Finish remaining for other missing details. ':''}Every card needs only a front photo. Back photos are optional at any price. Select all ready cards to approve them together; cards needing attention stay in the queue and do not block the rest.</p>${cards.length?`<section class="prep-bulk" aria-label="Bulk card approval"><div class="prep-bulk-summary"><strong id="prep-selection-count" role="status" aria-live="polite">${selectedListings.size} selected</strong><span>${ready} ready · ${attention} need attention${active?` · ${active} preparing`:''}</span></div><div class="prep-bulk-actions"><button class="btn" data-action="select-ready" ${ready?'':'disabled'}>${ready>500?'Select next 500 ready':`Select all ready (${ready})`}</button><button class="btn" data-action="edit-batch" ${finishCards().length?'':'disabled'}>${selectedListings.size?`Edit selected (${selectedListings.size})`:'Edit batch'}</button><button class="text-btn" data-action="clear-listings" ${selectedListings.size?'':'disabled'}>Clear selection</button><button class="btn primary" data-action="review-listings" data-write ${selectedListings.size?'':'disabled'}>Approve selected (${selectedListings.size})</button></div></section>`:''}<label class="field">Show cards<select id="prep-filter">${options([['all','All cards'],['ready','Ready for approval'],['attention','Needs attention'],['preparing','Preparing'],['approved','Approved']],prepFilter)}</select></label><p class="prep-guidance">Selection applies across filters. Select all ready includes ready cards in every view.</p><div class="prep-list">${cards.filter(d=>prepFilter==='all'||preparationStatus(d)===prepFilter).map(d=>{const issues=listingProblems(d),approved=approvedListings.has(d.id);return `<article class="panel prep-card" data-prep-card="${esc(d.id)}"><div class="prep-images">${d.photos.map(p=>`<a href="/api/photos/${esc(p.id)}/original" target="_blank" rel="noopener"><img src="/api/photos/${esc(p.id)}/preview" alt="${esc(p.role)} of ${esc(d.title||d.sku)}" loading="lazy"></a>`).join('')}</div><div class="panel-body"><div class="prep-title"><h2>${esc(d.title||'Preparing card details')}</h2><strong>${askingMoney(d.askCents)}</strong>${editPriceButton(d)}</div>${quickControls(d)}${priceNeedsReview(d)?'<p class="batch-error">Asking price needs your confirmation.</p>':''}<p>${esc(d.sku)} · ${esc(d.location)}</p><p>${esc(d.condition||'Condition needs review')} · ${d.photos.length} photo${d.photos.length===1?'':'s'}${photoRequirement(d).roles.length===1?' · Back photo optional':''}</p><p>${esc(d.description)}</p><p>${esc(d.conditionNotes)}</p>${assessmentDetails(d)}${issues.length?`<p class="batch-error">${issues.map(esc).join(' · ')}</p>`:''}<div class="actions"><button class="btn" data-draft="${esc(d.id)}">Edit details / photos</button>${approved?'<strong class="approved-label">Ready for listing</strong>':`<label class="checkbox"><input type="checkbox" data-review-card="${esc(d.id)}" aria-label="Select ${esc(d.title||d.sku)}" ${selectedListings.has(d.id)?'checked':''} ${issues.length?'disabled':''}>${issues.length?'Needs attention':'Select card'}</label>`}</div></div></article>`;}).join('')}</div>${cards.length?'':empty('No cards to prepare.','Upload your card photos first.',bulkIntakeButton())}`;
}

function finishCards(){return preparationCards().filter(d=>d.status==='draft'&&!approvedListings.has(d.id)&&!['queued','running'].includes(d.preparation?.status));}
function showFinishDetails(editing=false){
 finishEditing=editing;const cards=finishCards().filter(d=>editing?(!selectedListings.size||selectedListings.has(d.id)):listingProblems(d).length).slice(0,500);if(!cards.length){toast('No editable cards in this selection.');return;}finishSnapshots=new Map(cards.map(d=>[d.id,listingContent(d)]));finishDirty=false;
 modal(editing?'Edit card batch':'Finish remaining cards',`<p>${editing?`Edit prices and conditions for these ${cards.length} cards. Shared values replace that field in every displayed row; blank shared values leave it unchanged. Review before saving.`:'Enter the asking prices you have checked and any missing conditions. Old unconfirmed prices are shown for reference but their input stays blank. Saving a price confirms your choice. Leave anything uncertain blank.'} Photos save immediately.</p><form id="finish-form"><div class="finish-defaults form-grid">${field(editing?'Price for displayed cards ($)':'Price for blank rows ($)','defaultPrice','',{type:'number',min:1,step:'0.01'})}${conditionSelect(editing?'Condition for displayed cards':'Condition for blank rows','defaultCondition',{kind:'card'})}<button class="btn" type="button" data-action="fill-missing">${editing?'Apply to displayed cards':'Apply to blank fields'}</button></div><div class="finish-rows">${cards.map(d=>`<section class="finish-row" data-finish-row="${esc(d.id)}"><div class="finish-title">${artwork(d)}<div><strong>${esc(d.title||d.sku)}</strong><small>${esc(d.sku)} · ${askingMoney(d.askCents)} · ${esc(d.condition||'Condition needed')}</small></div></div><div class="form-grid">${editing||priceNeedsReview(d)||!Number.isSafeInteger(d.askCents)||roundAskingCents(d.askCents)<1?field('Asking price ($)','ask',editing&&!priceNeedsReview(d)&&d.askCents!=null?roundAskingCents(d.askCents)/100:'',{type:'number',min:1,step:'0.01'}):''}${editing||!d.condition?.trim()?conditionSelect('Listing condition','condition',{...d,condition:editing?d.condition:''}):''}</div><p class="finish-status" role="status"></p>${['front','back'].filter(role=>!d.photos.some(p=>p.role===role)).map(role=>`<label class="field"><span data-photo-label>Upload ${role} photo</span><input type="file" data-finish-photo="${esc(d.id)}" data-role="${role}" accept="image/jpeg,image/png,image/webp,image/heic"></label>`).join('')}<details><summary>Review description and condition notes</summary><p>${esc(d.description)}</p><p>${esc(d.conditionNotes)}</p></details></section>`).join('')}</div><p id="finish-count" role="status" aria-live="polite"></p><div class="actions"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary" data-write>Save details & select ready</button></div></form>`);
 updateFinishStatus();
}
function finishChanges(row){const changes={},ask=row.querySelector('[name="ask"]'),condition=row.querySelector('[name="condition"]');if(ask?.value.trim())changes.askCents=roundAskingCents(cents(ask.value));if(condition?.value.trim())changes.condition=condition.value.trim();return changes;}
function updateFinishStatus(){let ready=0;for(const row of document.querySelectorAll('[data-finish-row]')){const d=workspace.drafts.find(d=>d.id===row.dataset.finishRow);try{const changes=finishChanges(row),candidate={...d,...changes};if('askCents' in changes)candidate.priceReview=confirmPrice(candidate);const issues=listingProblems(candidate);for(const input of row.querySelectorAll('[data-finish-photo]'))input.closest('label').querySelector('[data-photo-label]').textContent=`Upload ${input.dataset.role} photo${photoRequirement(candidate).roles.includes(input.dataset.role)?'':' (optional)'}`;row.querySelector('.finish-status').textContent=issues.length?issues.join(' · '):'Ready after saving';if(!issues.length)ready++;}catch(e){row.querySelector('.finish-status').textContent=e.message;}}const count=$('#finish-count');if(count)count.textContent=`${ready} ready after saving. Other cards stay in the queue.`;}
async function saveFinishDetails(form){
 const rows=[...form.querySelectorAll('[data-finish-row]')],entries=[];
 for(const row of rows){const changes=finishChanges(row),original=Object.fromEntries(JSON.parse(finishSnapshots.get(row.dataset.finishRow)).fields);for(const key of Object.keys(changes))if(changes[key]===original[key]&&!(key==='askCents'&&priceNeedsReview(workspace.drafts.find(d=>d.id===row.dataset.finishRow))))delete changes[key];if(Object.keys(changes).length)entries.push({id:row.dataset.finishRow,fingerprint:await contentFingerprint(finishSnapshots.get(row.dataset.finishRow)),changes});}
 if(entries.length)await save('/preparation/details',{entries});else await load();
 finishDirty=false;selectedListings=new Map(readyListings().filter(d=>finishSnapshots.has(d.id)).map(d=>[d.id,listingContent(d)]).slice(0,500));prepFilter='all';close();render();
 toast(selectedListings.size?`${selectedListings.size} cards selected. Click Approve selected to confirm.`:'Details saved. Remaining cards still need the fields or photos shown.');
}
function fillMissingDetails(){try{const price=$('[name="defaultPrice"]').value,condition=$('[name="defaultCondition"]').value.trim();if(price)cents(price);for(const row of document.querySelectorAll('[data-finish-row]')){const a=row.querySelector('[name="ask"]'),c=row.querySelector('[name="condition"]');if(a&&(finishEditing||!a.value)&&price)a.value=price;if(c&&(finishEditing||!c.value)&&condition)c.value=condition;}finishDirty=true;updateFinishStatus();}catch(e){error(e);}}

function publicationCandidates(){const reserved=new Set(publication.batches.filter(b=>b.status!=='cancelled').flatMap(b=>b.entries.map(e=>e.draftId)));return workspace.drafts.filter(d=>approvedListings.has(d.id)&&d.status!=='archived'&&!reserved.has(d.id));}
function publicationView(){return heading('CARDS TO EBAY','Manage listings','Select, edit and publish from this page.',bulkIntakeButton()+newIntakeButton())+'<label class="field">Search cards<input id="intake-search" type="search" aria-label="Search intake" value="'+esc(draftQuery)+'" placeholder="Title, SKU or location"></label>'+deskSurface()+'<div id="intake-list">'+intakeList(true)+'</div>';}
function showPublicationReview(){const cards=publicationCandidates().slice(0,500);publicationSelection=cards.map(d=>({id:d.id,content:listingContent(d)}));modal('Prepare eBay batch',`<p>Select the approved cards to save together. This saves a review snapshot only; it does not authorize or publish listings. Next, choose your eBay shipping policy and condition details before the final publishing review.</p>${cards.map(d=>`<section class="finish-row"><label class="checkbox"><input type="checkbox" data-stage-card="${esc(d.id)}" checked>${esc(d.title)} · ${askingMoney(d.askCents)}</label><p>${esc(d.sku)} · ${esc(d.condition)} · ${esc(d.location)}</p><details><summary>Review photos and listing text</summary>${artwork(d)}<p>${esc(d.description)}</p><p>${esc(d.conditionNotes)}</p></details></section>`).join('')}<div class="actions"><button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="save-publication" data-write>Save eBay batch</button></div>`);}


let ebayOptions=null,ebaySettingsBatch=null,ebayReviewBatch=null;
function descriptorFields(d,condition){return (condition?.conditionDescriptors??[]).map(def=>{const id=def.conditionDescriptorId,c=def.conditionDescriptorConstraint??{};if(c.mode==='FREE_TEXT')return `<label class="field">${esc(def.conditionDescriptorName)}<input data-descriptor="${esc(id)}" data-card="${esc(d.id)}" value="${esc(id==='27503'?d.cert??'':'')}" maxlength="${Number(c.maxLength)||30}"></label>`;const values=def.conditionDescriptorValues??[];let match='';const sought=id==='27502'?String(d.grade??''):id==='27501'?String(d.gradeCompany??''):d.condition??'';const found=conditionValue(values,sought)??values.find(v=>v.conditionDescriptorValueName?.toLowerCase()===sought.toLowerCase()||(id==='27501'&&sought&&v.conditionDescriptorValueName?.startsWith(sought+' ')));if(found)match=found.conditionDescriptorValueId;return `<label class="field">${esc(def.conditionDescriptorName)}<select data-descriptor="${esc(id)}" data-card="${esc(d.id)}">${options([['','Choose…'],...values.map(v=>[v.conditionDescriptorValueId,v.conditionDescriptorValueName])],match)}</select></label>`;}).join('');}
function shippingFields(key,items,p){
 const rows=shippingChoices(p,key);
 return '<section class="finish-row" data-shipping-group="'+key+'"><h3>'+esc(shippingGroupLabel[key])+' · '+items.length+' cards</h3><details class="compact-card-list"><summary>View '+items.length+' cards in this shipping group</summary><ul>'+items.map(d=>'<li>'+esc(d.title)+'</li>').join('')+'</ul></details>'+ebayPolicySelect('Shipping for '+shippingGroupLabel[key],'ebay-shipping-'+key,rows,'fulfillmentPolicyId')+(['lot','review'].includes(key)?'<label class="field">Estimated label cost ($)<input data-shipping-estimate type="number" inputmode="decimal" min="0.01" step="0.01"></label><label class="checkbox"><input type="checkbox" data-shipping-cost-confirmed>I checked the packed-shipment cost and the buyer charge covers shipping and packaging. Do not reuse single-card postage.</label>':'')+'<div data-parcel-fields hidden><p>Calculated shipping needs the packed weight and size, including the envelope or mailer. Enter actual measurements that apply to every card in this group.</p><div class="form-grid">'+[['weight_oz','Packed weight (oz)'],['length_in','Length (in)'],['width_in','Width (in)'],['height_in','Thickness (in)']].map(([name,label])=>'<label class="field">'+label+'<input data-parcel="'+name+'" inputmode="decimal" type="number" min="0.001" step="0.001" aria-label="'+label+'"></label>').join('')+'</div><label class="checkbox"><input type="checkbox" data-parcel-verified>I measured the packed weight and dimensions; they apply to every card in this group.</label><div data-envelope-note hidden><p>Standard Envelope: raw cards up to $20; up to 3 oz; 5–11.5 inches long, 3.5–6.125 inches wide, less than 0.25 inches thick.</p><label class="checkbox"><input type="checkbox" data-envelope-confirmed>These are flexible, uniformly thick paper/card envelopes that meet those limits, not plastic or rigid mailers.</label></div></div></section>';
}
function ebayPolicySelect(label,name,rows,idKey){return '<label class="field">'+esc(label)+'<select id="'+name+'" aria-label="'+esc(label)+'">'+options([['','Choose…'],...rows.map(r=>[r[idKey],String(r.name??r[idKey]).replace(/\s*\(\d+\)$/,'')])],rows.length===1?rows[0][idKey]:'')+'</select></label>';}
function updateShippingFields(){
 for(const row of document.querySelectorAll('[data-shipping-group]')){
  const policy=(ebayOptions.policies.fulfillment_policy?.fulfillmentPolicies??[]).find(p=>p.fulfillmentPolicyId===row.querySelector('select').value);
  row.querySelector('[data-parcel-fields]').hidden=!isCalculated(policy)&&!['lot','review'].includes(row.dataset.shippingGroup);
  row.querySelector('[data-envelope-note]').hidden=!isEnvelope(policy);
 }
}
async function showEbaySettings(id,category='261328',inline=false){
 ebaySettingsBatch=id;ebayOptions=await api('/ebay/options?category='+category);paintEbaySettings(id,category,inline);
}
function paintEbaySettings(id,category='261328',inline=false){
 ebaySettingsBatch=id;
 const b=publication.batches.find(b=>b.id===id),p=ebayOptions.policies,conditions=ebayOptions.category.itemConditionPolicies?.[0]?.itemConditions??[];
 const cards=b.entries.map(e=>workspace.drafts.find(d=>d.id===e.draftId)),groups=[...new Set(cards.map(shippingGroup))],campaigns=campaignChoices(p);
 const settingsBody='<p>PWE singles share one saved setup. Cards over $20, graded cards and lots use separate parcel shipping.</p>'+
 '<details id="desk-account-settings"><summary>eBay account settings</summary><label class="field">Category<select id="ebay-category">'+options([['261328','Sports trading cards'],['183050','Non-sport trading cards'],['183454','Collectible card games']],category)+'</select></label><button class="btn" data-action="ebay-category" data-batch-id="'+esc(id)+'">Load category</button>'+
 '<input type="hidden" id="ebay-payment" value="'+esc(paymentPolicy(p,ebayOptions.defaults?.paymentPolicyId)?.paymentPolicyId??'')+'"><p>Payment: '+esc(paymentPolicy(p,ebayOptions.defaults?.paymentPolicyId)?.name??'eBay payment policy unavailable — retry loading settings')+' · applied automatically</p>'+
 ebayPolicySelect('Returns','ebay-returns',p.return_policy?.returnPolicies??[],'returnPolicyId')+
 ebayPolicySelect('eBay inventory location','ebay-location',(p.locations?.locations??[]).filter(l=>l.merchantLocationStatus==='ENABLED'),'merchantLocationKey')+
 ebayPolicySelect('Existing 5% promotion campaign','ebay-campaign',campaigns,'campaignId')+
 '<p>'+(campaigns.length?'Only eligible existing fixed 5% campaigns are shown. Core will not change campaign rates or selection rules.':'No eligible existing fixed 5% campaign was returned by eBay. No campaign has been created or changed.')+'</p>'+
 '</details>'+groups.map(key=>shippingFields(key,cards.filter(d=>shippingGroup(d)===key),p)).join('')+'<details><summary>View full existing policies</summary>'+readableFields(p)+'</details><label class="checkbox"><input id="ebay-combined" type="checkbox">I confirm buyer-paid and combined shipping for the selected policies.</label>'+
 '<h3>Review eBay conditions</h3><p>Open a card to inspect or change its eBay condition. Cards needing a choice are expanded.</p>'+cards.map(d=>{const condition=conditions.find(c=>c.conditionId===(d.gradeCompany?'2750':'4000'));return '<details class="finish-row ebay-card-condition" data-ebay-card="'+esc(d.id)+'" data-condition="'+esc(condition?.conditionId??'')+'"><summary><strong>'+esc(d.title)+' · '+askingMoney(d.askCents)+'</strong><span data-condition-summary></span></summary><p>'+esc(d.sku)+' · Previous assessment: '+esc(d.condition)+' · '+esc(d.conditionNotes)+'</p>'+artwork(d)+descriptorFields(d,condition)+'</details>';}).join('')+
 '<div class="actions"><button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="ebay-configure" data-batch-id="'+esc(id)+'">Continue to final review</button></div>';
 if(inline){$('#desk-shipping').innerHTML=settingsBody.replace('data-action="ebay-category"','data-action="desk-category"').replace('<button class="btn" data-action="close">Cancel</button>','').replace('data-action="ebay-configure"','data-action="desk-configure"').replace('Continue to final review','Get '+cards.length+' selected ready to publish');}else modal('Choose shipping',settingsBody);
 for(const row of document.querySelectorAll('[data-ebay-card]')){const controls=[...row.querySelectorAll('[data-descriptor]')],update=()=>{const missing=!controls.length||controls.some(el=>!el.value);row.querySelector('[data-condition-summary]').textContent=missing?'Choose eBay condition':controls.map(el=>el.tagName==='SELECT'?el.selectedOptions[0]?.textContent:el.value).join(' · ');if(missing)row.open=true;};for(const el of controls)el.addEventListener('change',update);update();}
 const defaults=ebayOptions.defaults;
 const automaticLocation=inventoryLocation(p,defaults?.locationKey);if(automaticLocation)$('#ebay-location').value=automaticLocation.merchantLocationKey;
 if(inline&&defaults)$('#ebay-combined').checked=true;
 for(const [name,key] of [['returns','returnPolicyId'],['location','locationKey'],['campaign','campaignId']]){const el=$('#ebay-'+name);if(defaults?.[key]&&[...el.options].some(o=>o.value===defaults[key]))el.value=defaults[key];}
 const pweRow=$('[data-shipping-group="raw"]');
 if(pweRow){
  const select=pweRow.querySelector('select'),pure=(p.fulfillment_policy?.fulfillmentPolicies??[]).filter(policy=>isEnvelope(policy)&&(policy.shippingOptions??[]).every(o=>(o.shippingServices??[]).every(s=>(s.shippingServiceCode??'').toLowerCase().replaceAll('_','').includes('ebaystandardenvelope'))));
  const saved=defaults?.pwe,validSaved=saved&&[...select.options].some(o=>o.value===saved.fulfillmentPolicyId);
  if(validSaved)select.value=saved.fulfillmentPolicyId;else if(pure.length===1)select.value=pure[0].fulfillmentPolicyId;
  if(validSaved&&saved.parcel){for(const input of pweRow.querySelectorAll('[data-parcel]'))input.value=saved.parcel[input.dataset.parcel]??'';pweRow.querySelector('[data-parcel-verified]').checked=true;pweRow.querySelector('[data-envelope-confirmed]').checked=true;pweRow.insertAdjacentHTML('afterbegin','<p class="note">Saved measured PWE setup applied to all eligible singles. Change it if your packaging changes. Parcel and lot measurements are never copied from PWE.</p>');}
 }
 for(const row of document.querySelectorAll('[data-shipping-group]'))row.querySelector('select').addEventListener('change',updateShippingFields);
 if(inline){restoreDeskInputs();const rows=[...document.querySelectorAll('#desk-shipping [data-ebay-card]')];if(rows.length&&rows.every(r=>!r.open)){const more=document.createElement('details');more.className='desk-condition-details';more.innerHTML='<summary>eBay condition details ('+rows.length+')</summary>';rows[0].before(more);for(const r of rows)more.append(r);}}
 updateShippingFields();
 const account=$('#desk-account-settings');if(account)account.open=['payment','returns','location','campaign'].some(key=>!$('#ebay-'+key)?.value);
}
function parcelSummary(parcel){return parcel?'<p><strong>Measured packed parcel:</strong> '+esc(parcel.weight_oz)+' oz · '+esc(parcel.length_in)+' × '+esc(parcel.width_in)+' × '+esc(parcel.height_in)+' in</p>':'';}
function batchPolicySummary(bridge){
 return bridge.settings.shippingGroups?Object.values(bridge.settings.shippingGroups).map(g=>'<section><h3>'+esc(g.label)+'</h3>'+policySummary(g.snapshot,bridge.campaignSnapshot)+parcelSummary(g.parcel)+(g.costReview?'<p>Owner-reviewed label cost estimate: '+money(g.costReview.estimatedLabelCents)+'; buyer shipping and packaging charge checked.</p>':'')+'</section>').join(''):policySummary(bridge.policySnapshot,bridge.campaignSnapshot);
}
function showEbayFinalReview(id){
 const b=publication.batches.find(b=>b.id===id);ebayReviewBatch={id,fingerprint:b.bridge.reviewFingerprint};
 const listings=b.bridge.reviews.flatMap(r=>r.listings);
 modal('Review eBay listings',`<p class="flow-steps">Step 3 of 3 · Review & publish</p><p>${listings.length} listings will be published at the exact prices below. Cards with errors are excluded. No automatic retry after a confirmed eBay rejection is authorized.</p><details open><summary>Shipping, payment, returns and 5% promotion</summary>${batchPolicySummary(b.bridge)}</details>${listings.map(l=>{const e=b.entries.find(e=>'btco-card-'+e.draftId===l.draft_id),d=l.draft,choice=b.bridge.settings.cards[e.draftId];return `<section class="finish-row"><h3>${esc(d.title)} · $${esc(d.price_usd)}</h3><p>${esc(d.master_sku)} · Storage: ${esc(e.location)} · ${d.condition==='LIKE_NEW'?'Graded':'Ungraded'}</p>${e.photos.map(p=>`<a href="/api/photos/${esc(p.id)}/original" target="_blank" rel="noopener"><img class="review-card-image" src="/api/photos/${esc(p.id)}/preview" alt="${esc(p.role)} original of ${esc(d.title)}"></a>`).join('')}<p>${esc(d.description)}</p><p>${esc(d.condition_description)}</p><p>${d.best_offer.enabled?`Offers on · minimum $${esc(d.best_offer.minimum_offer_usd)}`:'Offers off'} · Buyer-paid combined shipping · 5% promotion</p><p><strong>Shipping:</strong> ${esc(b.bridge.settings.shippingGroups?.[shippingGroup(workspace.drafts.find(x=>x.id===e.draftId))]?.snapshot?.fulfillment_policy?.name??b.bridge.policySnapshot?.fulfillment_policy?.name??d.policies.fulfillment_policy_id)}</p>${parcelSummary(d.packed_parcel)}<p><strong>Condition:</strong> ${esc((choice.labels??[]).join(" · "))}</p>${readableFields(d.item_specifics)}</section>`;}).join('')}<label class="checkbox"><input id="ebay-final-confirm" type="checkbox">I reviewed the original photos, full listing text, prices, condition, shipping and promotion for all ${listings.length} listings and approve publishing them.</label><div class="actions"><button class="btn" data-action="close">Keep reviewing</button><button class="btn primary" data-action="ebay-approve" data-batch-id="${esc(id)}">Approve and publish ${listings.length} listings</button></div>`);
}
async function runEbayPreparation(id,inline=false){
 let next=true;while(next){const r=await api('/ebay/prepare',{method:'POST',data:{id}});next=r.continuePreparation;await load();if(!inline)view='publication';deskProgress='Preparing '+(publication.batches.find(b=>b.id===id)?.bridge?.entries.filter(e=>e.status!=='pending').length??0)+' of '+(publication.batches.find(b=>b.id===id)?.entries.length??0)+' cards…';render();}
 const b=publication.batches.find(b=>b.id===id);if(inline){deskProgress='';render();return;}if(b?.bridge?.reviews?.some(r=>r.listings.length))showEbayFinalReview(id);else toast('Some cards need attention. See their errors below.');
}
async function runEbayPublish(id,approve=false){
 let b=publication.batches.find(b=>b.id===id),fingerprint=b.bridge.reviewFingerprint;
 let result=await api('/ebay/'+(approve?'approve':'publish'),{method:'POST',data:{id,reviewFingerprint:fingerprint}});await load();view='publication';render();
 // A failed card can release the next ready card without increasing verified.
 // Only the server's journal-based signal advances; waiting/unknown work pauses.
 while(!result.complete&&result.continueAutomatically){result=await api('/ebay/publish',{method:'POST',data:{id,reviewFingerprint:fingerprint}});await load();render();}
 if(result.complete)sessionStorage.removeItem(pendingListingKey);toast(result.complete?'All prepared listings are verified live.':'Progress saved. Check the status before continuing.');
}
async function ebayAction(action,id){
 if(action==='ebay-connect'){if(quickEdits.size||finishDirty)throw Error('Save or discard unsaved edits before connecting eBay.');const r=await api('/ebay/connect',{method:'POST',data:{}});location.assign(r.url);return;}
 if(action==='ebay-disconnect'){await api('/ebay/disconnect',{method:'POST',data:{}});await load();render();return;}
 const saved=await saveQuickRows();if(saved?.batchReplacements?.[id]){await continueListingFlow(saved.batchReplacements[id]);return;}
 if(action==='ebay-continue'){await continueListingFlow(id);return;}
 if(action==='ebay-settings'){await showEbaySettings(id);return;}
 if(action==='ebay-category'){await showEbaySettings(id,$('#ebay-category').value);return;}
 if(action==='ebay-configure'){
  const settings=collectEbaySettings();
  await api('/ebay/configure',{method:'POST',data:{id,settings}});close();await runEbayPreparation(id);return;
 }
 if(action==='ebay-prepare'){await runEbayPreparation(id);return;}
 if(action==='ebay-refresh'){await api('/ebay/refresh',{method:'POST',data:{id}});await load();render();return;}
 if(action==='ebay-review'){await api('/ebay/refresh',{method:'POST',data:{id}});await load();showEbayFinalReview(id);return;}
 if(action==='ebay-approve'){if(!$('#ebay-final-confirm')?.checked)throw Error('Confirm the complete listing review first.');const b=publication.batches.find(b=>b.id===id);if(ebayReviewBatch?.fingerprint!==b.bridge.reviewFingerprint)throw Error('Review changed. Open it again.');close();await runEbayPublish(id,true);return;}
 if(action==='ebay-resume')await runEbayPublish(id);
}

