 return '<p class="desk-row-status '+(issues.length||remote?'needs-attention':'')+'">'+esc(remote??(issues.length?issues.join(' · '):b?.status==='ready'?'Ready to publish':b?.status==='publishing'?'Publication in progress':'Details saved'))+'</p>';
