 if(card){const d=workspace.drafts.find(d=>d.id===card.dataset.ebayCard);return 'card:'+card.dataset.ebayCard+':'+[d?.condition,d?.gradeCompany,d?.grade,d?.cert].join('|')+':'+el.dataset.descriptor;}
 if(group){const key=group.dataset.shippingGroup,scope=key==='raw'?'pwe':deskBatch()?.entries.filter(e=>shippingGroup(workspace.drafts.find(d=>d.id===e.draftId))===key).map(e=>e.draftId).sort().join(',');return key+':'+scope+':'+(el.dataset.parcel??[...el.attributes].find(a=>a.name.startsWith('data-'))?.name);}
