function captureDeskInputs(){for(const el of document.querySelectorAll('#desk-shipping input:not([type="hidden"]),#desk-shipping select')){const key=deskInputKey(el);if(key)deskInputs.set(key,{value:el.value,checked:el.checked});}}
function restoreDeskInputs(){for(const el of document.querySelectorAll('#desk-shipping input:not([type="hidden"]),#desk-shipping select')){const v=deskInputs.get(deskInputKey(el));if(!v||el.id==='ebay-location'&&!v.value&&el.value)continue;if(el.tagName==='SELECT'&&![...el.options].some(o=>o.value===v.value))continue;el.value=v.value;if(el.type==='checkbox')el.checked=v.checked;}}
async function loadDeskOptions(){deskOptions=await api('/ebay/options?category='+deskCategory);renderDeskPanel();}
async function beginDeskSelection(){
 if(!bulkSelection.size)throw Error('Select cards to publish.');
 if($('#desk-bulk:not([hidden])'))throw Error('Save your bulk edits first.');
 captureDeskInputs();deskFocused=true;deskWorking=true;deskProgress='Saving the selected cards…';
 try{
  const ids=[...bulkSelection];await saveQuickRows(ids);
  const entries=await Promise.all(ids.map(async id=>{const d=workspace.drafts.find(d=>d.id===id);return {id,fingerprint:await contentFingerprint(listingContent(d))};}));
  const result=await save('/publication/selection',{entries,confirmedDetails:true});deskBatchId=result.batchId;deskExcluded=result.excluded??[];deskProgress='';
  bulkSelection.clear();if(!result.count){sessionStorage.removeItem(pendingListingKey);render();return;}for(const e of deskBatch().entries)bulkSelection.add(e.draftId);
  sessionStorage.setItem(pendingListingKey,deskBatchId);location.hash=view;render();
  if(!publication.connection?.connected)return;
  const b=deskBatch();if(b.bridge){if(b.status==='preparing')await runEbayPreparation(b.id,true);return;}
  await loadDeskOptions();
  // A previously confirmed setup can proceed immediately. Missing choices stay on this page.
  let settings;try{settings=collectEbaySettings();}catch(e){deskProgress=e.message;return;}
  await api('/ebay/configure',{method:'POST',data:{id:b.id,settings}});await load();await runEbayPreparation(b.id,true);
 }catch(e){deskProgress='';throw e;}finally{deskWorking=false;render();if(deskProgress){const p=$('#desk-panel');p?.insertAdjacentHTML('afterbegin','<p class="batch-error">'+esc(deskProgress)+'</p>');deskProgress='';}$('#desk-panel')?.scrollIntoView({block:'start'});}
}
async function deskAction(action,button){
 if(action==='desk-save-fixes'){await saveDeskFixes();return;}
 if(action==='desk-close-bulk'){if(finishDirty&&!confirm('Discard unsaved bulk edits?'))return;finishDirty=false;$('#desk-bulk').hidden=true;return;}
 if(action==='desk-prepare'){await beginDeskSelection();return;}
 if(action==='desk-resume'){await continueListingFlow(button.dataset.batchId);return;}
 if(action==='desk-load-options'){await loadDeskOptions();return;}
 if(action==='desk-category'){captureDeskInputs();deskCategory=$('#ebay-category').value;deskInputs.delete('ebay-category');await loadDeskOptions();return;}
 if(action==='desk-configure'){
  if(!sameSelection(deskBatch(),bulkSelection))throw Error('Selection changed. Get this selection ready first.');
  if([...bulkSelection].some(id=>quickEdits.has(id)))throw Error('Save the card edits and get the selection ready again.');
  captureDeskInputs();const settings=collectEbaySettings();deskWorking=true;deskProgress='Checking eBay settings…';
  try{await api('/ebay/configure',{method:'POST',data:{id:deskBatchId,settings}});await load();await runEbayPreparation(deskBatchId,true);}finally{deskWorking=false;deskProgress='';render();}
  return;
 }
 if(action==='desk-publish'){
  const b=deskBatch(),fingerprint=button.dataset.reviewFingerprint;
  if(!b||b.id!==button.dataset.batchId||fingerprint!==b.bridge?.reviewFingerprint)throw Error('The prepared listings changed. Refresh before publishing.');
  if(b.status!=='publishing'&&(!sameSelection(b,bulkSelection)||[...bulkSelection].some(id=>quickEdits.has(id))))throw Error('Your selection or edits changed. Get this selection ready before publishing.');
  if(!['ready','publishing'].includes(b.status))throw Error('These cards are not ready to publish.');
  const count=(b.bridge.reviews??[]).flatMap(r=>r.listings).filter(l=>!l.publication?.all_checks_verified).length;
  if(b.status==='ready'&&!confirm('Are you sure you want to publish '+count+' cards to eBay at the shown prices and shipping?'))return;
  deskWorking=true;deskProgress='Publishing selected cards…';
  try{
   let result=await api('/ebay/'+(b.status==='ready'?'approve':'publish'),{method:'POST',data:{id:b.id,reviewFingerprint:fingerprint}});await load();render();
   while(!result.complete&&result.continueAutomatically){deskProgress=result.verified+' verified live…';result=await api('/ebay/publish',{method:'POST',data:{id:b.id,reviewFingerprint:fingerprint}});await load();render();}
   if(result.complete){bulkSelection.clear();sessionStorage.removeItem(pendingListingKey);toast(result.verified+' listings verified live on eBay.');}
   else toast('Progress saved. Review the status here before continuing.');
  }finally{deskWorking=false;deskProgress='';render();}
 }
}
